window.MA = {"schemaVersion":1,"taxonomy":{"carriers":{"video":"影像视频","console":"交互操作台","showcase":"交互展示台"},"sources":{"reference":"用户提供的参考","game":"游戏界面转译","original":"原创设计语言"},"types":{"composition":"画面构成","type-motion":"文字动效","transition":"转场","camera":"镜头与空间","feedback":"交互反馈","rhythm":"节奏与时序","hud":"信息层 HUD","texture":"质感与后期","sound":"声音"},"evidence":{"observed":"逐帧/源码实测","adapted":"本地转译","inferred":"公开资料推断·待核验","original":"原创设计"},"roles":{"foundation":"骨架：决定主视觉与信息层级","support":"支撑：承担一个区域的交互或信息","accent":"点睛：短时、局部的强调"}},"cases":[{"id":"map-pilgrimage","order":1,"title":"地图巡礼 · 游戏过场式旅行影像","subtitle":"CARTOGRAPHIC PILGRIMAGE / MAP × HUD × MEMORY","carriers":["video","showcase"],"source":"reference","evidence":"observed","capturedAt":"2026-10-14","tags":["地图叙事","游戏过场","HUD 四角","昼夜切换","分屏对比","竖排汉字"],"summary":"以真实地图为“交互基地”，四角 HUD 记录日序、坐标、时间与音乐；镜头沿路线推进，在卡片、全屏实拍、动画回忆与分屏对比之间切换，把一段旅行剪成游戏过场。","focus":"参考视频 151 秒、1920×1080，由 Agent 用旅行素材自动剪辑。它的价值不在某个特效，而在“一个稳定的世界层 + 一套持续更新的信息层 + 有节制的模式切换”：地图永远是底座，HUD 永远在报时，只有高光才允许离开地图。Demo 用原创内容（江南三日）完整复现这套结构，所有时间点都写在 config.js 的轨道里。","accent":"#d9632b","background":"#f2efe8","timeline":true,"kit":true,"energy":[0.15,0.2,0.6,0.5,0.45,0.55,0.6,0.72,0.55,0.8,0.78,0.75,0.45,0.4,0.6,0.55,0.88,0.6,0.5,0.62,0.45,0.35,0.3,0.2],"rhythm":{"duration":56,"beats":[{"t":0,"label":"冷开场","note":"夜间地球缓推，起终点标记依次出现并打字标注。"},{"t":3.3,"label":"昼夜翻转","note":"暗 → 灰 → 亮约 0.9s，画面先变灰再变亮，像“天亮了”。"},{"t":4,"label":"片名","note":"竖排汉字自上而下逐字模糊入场（140ms 错峰），横线描出，英文带模糊前沿打字。"},{"t":7.6,"label":"HUD 上线","note":"四角信息从各自边缘轻移入场：日序、坐标、时钟、正在播放、旅程步进。"},{"t":8.2,"label":"航线","note":"虚线航线随镜头飞越逐段描出，头部圆点领路。"},{"t":11.6,"label":"抵达","note":"竖排地名 + 英文地点；照片卡片从右侧浮入，引线连到地图标记。"},{"t":15.8,"label":"卡片 → 全屏","note":"卡片 0.6s 展开为全屏实景，HUD 保留并转为白字压暗层；3s 后收回。"},{"t":20.6,"label":"章节主题","note":"章节标签 + 强调色替换 + 屏幕四角框线描出，宣布进入一个“作品/主题”。"},{"t":21.6,"label":"回忆","note":"全屏插画风回忆：独立框线、档案标签、竖排字幕逐字、英文字幕打字、颗粒加重。"},{"t":25.2,"label":"分屏对比","note":"先切到实景全屏，分割线从左滑到中线露出旧明信片，倾斜时间戳盖章落下。"},{"t":29.4,"label":"入夜 · 便签","note":"底图逐层变为夜色；通知条与手写便签卡片弹出又收回。"},{"t":33,"label":"DAY 02","note":"大号日序：DAY 描边 + 数字实心滚入，同时天亮。"},{"t":38.1,"label":"意外 · 改道","note":"红色警示横幅从左擦入，错误路线画红并打叉，黑色 REROUTING 胶囊闪烁省略号。"},{"t":44.3,"label":"终点城市","note":"夜景竖卡 + 3D 建筑，收集托盘最后一格点亮。"},{"t":49.8,"label":"全程鸟瞰","note":"镜头拉远到全线路，所有标记与路线同屏。"},{"t":51,"label":"结尾统计","note":"数字逐行计数堆叠（320ms 错峰），衬线 fin. 与署名、致谢。"}]},"layers":[{"name":"世界层","role":"真实底图（MapLibre + OpenFreeMap），镜头关键帧驱动；昼夜按图层逐个插值配色。"},{"name":"路线层","role":"航线虚线、地面实线、错误路线红线，均在 GL 图层内绘制以保证大俯仰角下的透视与裁切。"},{"name":"媒体层","role":"照片卡片、全屏实景、插画回忆、分屏对比；同一时间只有一种全屏媒体。"},{"name":"信息层 HUD","role":"四角固定：左上日序与日期、右上坐标/海拔/缩放与时钟、左下正在播放与双语歌词、右下旅程步进与收集托盘。"},{"name":"事件层","role":"地名标题、章节标签、警示横幅、通知、便签、日序大字——短暂出现、有明确入出场。"},{"name":"质感层","role":"按时间选帧的颗粒（可复现）、回忆段加重；全屏图片时上下压暗。"}],"composition":{"color":"白天米白纸色 #f2efe8 + 墨色文字；夜晚深蓝黑；默认橙色强调，每个章节换一种强调色（青、蓝、红、紫）并同步到路线、卡片描边、框线。","typography":"三套字体各司其职：粗黑竖排汉字做地名与片名；工业感无衬线（Bahnschrift/DIN 类）做英文标题；等宽字体做坐标、时间、标签，字距放宽 0.12–0.24em；结尾用衬线营造“落幕”。","layout":"四角 HUD 固定、中央留给世界；卡片靠右、标题靠左上，形成对角平衡；一条贯穿顶部的细线承载进度。","imagery":"实拍卡片带阴影与细描边；回忆用高饱和柔光插画；对比用旧明信片（棕褐、纸边、暗角）对现代实景。","motion":"镜头缓入缓出、长时运动；文字用“模糊→清晰”的逐字入场；卡片 550ms 浮入、600ms 展开；时间戳盖章用回弹。","sound":"参考视频有完整配乐与歌词；Demo 不提供音轨，仅在开启后合成标记、展开、计数、盖章、警示的短音。","rhythm":"约每 4–6 秒一个事件，每 10–15 秒一次模式切换（地图 ↔ 全屏），高光前后留 1–2 秒地图呼吸。","coherence":"所有模式共享同一套 HUD 和颗粒，所以全屏、回忆、对比都像同一个“系统”里的不同视图，而不是硬拼剪辑。"},"tokens":{"palette":["#f2efe8","#16171a","#d9632b","#1f8f84","#3d58c8","#e5483b","#090c12"],"type":"粗黑 CJK 竖排 + DIN 类英文 + 等宽数据 + 衬线结尾","motion":[{"name":"blur-in 逐字","value":"500ms outCubic，字间 140–160ms，模糊 14px → 0，上移 10px → 0"},{"name":"type-in 打字","value":"按字符推进，前沿 2 个字符带 6px 模糊"},{"name":"card-in","value":"550ms outCubic：透明 0→1、上移 26px→0、缩放 0.965→1"},{"name":"card-expand","value":"600ms inOutCubic 展开，停 3s，550ms 收回；停留期 Ken Burns 1→1.07"},{"name":"day-night","value":"约 0.9–1.2s，逐图层插值；中间经过灰阶"},{"name":"frame-draw","value":"800ms inOutCubic 描边；四角方块 120ms 错峰回弹"},{"name":"stamp","value":"380ms outBack，缩放 1.45→1，旋转 -4°"},{"name":"stat-stack","value":"每行 320ms 错峰，计数 900ms outQuart"}]},"observations":[{"at":"0:00–0:05","what":"深色太空中地球自转推近，首尔与关西标记带英中标签依次出现；左下已在显示 NOW PLAYING。"},{"at":"0:05.2–0:06.1","what":"亮度交叉：暗 → 灰 → 亮，约 0.9 秒完成“天亮”。"},{"at":"0:06.4–0:07.0","what":"竖排「聖地巡礼」逐字模糊入场，横线描出，PILGRIMAGE '26 从左向右打出且前沿模糊。"},{"at":"0:16.5","what":"HUD 全貌：DAY 01 / 07、MON · SEP 28 2026、34.4320°N 135.2304°E、ELEV 0 M · Z 10.9、11:33 JST、YUI SPOTTED ×2、NOW PLAYING 曲名 — 艺人、SEOUL–KANSAI–KYOTO–TOKYO 步进器、右下地图署名。"},{"at":"0:20.6–0:22.7","what":"照片卡片在地图上切换，地名竖排模糊入场；22.7 秒硬切为全屏实拍，HUD 保留。"},{"at":"0:38.9–0:41.0","what":"夜 → 昼的同时出现 DAY 02（DAY 描边、02 实心）；章节主题出现时屏幕四角框线描出、强调色变为该作品的蓝色。"},{"at":"0:55.2–0:57.9","what":"全屏动画回忆：蓝色内框、FLASHBACK · S1 EP05 标签、竖排日文字幕逐字揭示、英文字幕打字、底部场景说明，颗粒明显。"},{"at":"1:12–1:20","what":"角色收集托盘：四个角色位依次点亮，与计数徽章 ×11 呼应。"},{"at":"1:39.35–1:40.6","what":"动画 → 实景经暗场交叉；分割线从左滑到中线，ANIME · 2015 / REAL · 2026 标签，倾斜描边时间戳“10.01 · 18:20 JST”。"},{"at":"2:08.5","what":"红色通栏 ⚠ WRONG TRAIN + 线路说明，黑色 ◀◀ REROUTING… 胶囊；错误路线画红并以叉号收尾。"},{"at":"2:30.5","what":"结尾统计堆叠：7 DAYS · 2 COUNTRIES / 5 WORKS VISITED / 3 NOTES LEFT / ×19 SIGHTINGS / 1,159 km，衬线「聖地巡礼 — fin.」与署名、音乐与动画出处。"}],"interaction":["影像模式：空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个节拍；站内刻度条可拖动并显示节拍与能量曲线。","展示台用法：把 config.js 的 tracks 当作剪辑轨道，修改时间即改变节奏；?t=秒 可直接定位任一画面。","逐帧渲染：?render=1 关闭自动播放，每次 seek 等待地图瓦片完成再返回，scripts/render.mjs 据此导出帧序列。","离线或地图服务不可用时自动退回网格底图，HUD、路线、卡片与转场保持完整。"],"useCases":["旅行 / 巡礼 Vlog","城市与文旅宣传","物流与路线回顾","活动巡回纪录","年度回顾影像","交互式行程展示台"],"avoid":["没有空间移动的内容","需要逐字阅读的长文","镜头要停在单一画面的访谈"],"constraints":["参考视频为 B 站公开作品，Demo 只学习结构与节奏，画面、文字、地点与音乐全部替换为原创或公有领域内容。","参考视频中的动画截图与音乐属于各自权利人，本库不收录其帧画面。","底图使用 OpenFreeMap（OpenStreetMap 数据），必须保留署名；高缩放下的 3D 建筑依赖 render_height 数据，各城市覆盖不同。","程序化“照片”只用于示意；正式作品请在 config.js 填入有权使用的真实照片。","所有文字最终字号 ≥ 12px；成片 1920×1080 下的 HUD 小字为 12px，缩放预览时属于视频画面。"],"prompt":"用 HTML/CSS/JS 制作一支 50–60 秒、可逐帧定位的“地图巡礼”影像（1920×1080，同时适配窄屏）。结构：①世界层：MapLibre + OpenFreeMap positron 底图，隐藏全部文字标注，增加 3D 建筑；镜头用关键帧 {t, center, zoom, pitch, bearing} 缓入缓出，长距离移动中途降低缩放形成弧线飞行；开场用地球投影。②昼夜：按图层类别（背景/水/绿地/道路/建筑/3D 建筑）逐个插值白天与夜晚配色，过渡约 1 秒、中途经过灰阶，不要整体反色。③路线：航线虚线、地面实线（白色描边+强调色）、错误路线红线，放进 GL 图层绘制，按进度截断并带头部圆点。④HUD 四角常驻：左上“DAY 01 / 03”与等宽日期，右上纬经度、ELEV·Z 缩放与大号时钟+时区角标，右侧胶囊计数徽章（变化时数字上滚+回弹），左下 NOW PLAYING + 双语歌词（打字），右下旅程步进器与收集托盘；顶部细线随旅程进度填充强调色。⑤事件：竖排粗黑汉字逐字模糊入场（500ms，字间 140ms）+ 英文带模糊前沿打字；照片卡片 550ms 浮入并用虚线连到地图标记；卡片 600ms 展开为全屏实景、HUD 保留并加上下压暗层；章节主题出现时替换强调色并描出屏幕四角框线；全屏插画回忆带独立框线、档案标签、竖排字幕逐字；分屏对比先实景全屏、分割线 700ms 从左滑至中线露出旧明信片，倾斜描边时间戳以回弹盖章；红色警示横幅从左擦入 + 黑色 REROUTING 胶囊；大号日序 DAY 描边 + 数字实心滚入；结尾统计逐行计数堆叠 + 衬线 fin.。⑥节奏：每 4–6 秒一个事件，每 10–15 秒一次地图↔全屏切换，高光前后留 1–2 秒地图呼吸。⑦工程：画面写成 render(t) 纯函数，所有时间写进一个 config 轨道对象；暴露 window.__motion = {duration, seek(t)→Promise, play, pause, on}；?render=1 时 seek 等待地图 idle；颗粒按时间选帧以便复现；声音默认关闭；prefers-reduced-motion 时不自动播放并停在一帧完整构图；离线退回网格底图。所有文字 ≥12px。","videoPrompt":"1920×1080 travel cutscene in the style of a video-game map interface, 55 seconds. A pale paper-colored 3D map (light warm grey land, blue-grey water, white roads, extruded white buildings) is the persistent world; the camera glides along a route with slow ease-in-out moves and gentle pitch. Fixed HUD in four corners: top-left 'DAY 01 / 03' with a small date in monospace, top-right latitude/longitude, 'ELEV 7 M · Z 11.2' and a large digital clock with 'CST' superscript, bottom-left 'NOW PLAYING' with an equalizer icon and bilingual lyric lines, bottom-right a 4-stop journey progress stepper. Beats: dark night globe → brightness flips to day through grey → giant vertical Chinese title characters blur in one by one with an English title typing in → a dashed flight arc draws across the map → arrival: a vertical Chinese place name blurs in, a photo card floats in on the right with a thin dashed leader line to the map pin → the card expands to full screen while the HUD stays on top → a chapter tag appears and an accent-colored frame draws around the screen edges with square corner caps → an anime-style flashback with its own frame and vertical subtitles revealing character by character → split-screen comparison: a divider slides from the left edge to center revealing an old sepia postcard against a modern photo, a tilted outlined timestamp stamps down → night falls on the map layer by layer → a red 'WRONG TRAIN' banner wipes in, the wrong route turns red and ends with an X → ends with stacked statistics counting up and a serif 'fin.'. Clean, restrained, game-UI precision, subtle film grain, no camera shake.","negativePrompt":"不要整体反色做夜景；不要让多个全屏模式叠在一起；不要把 HUD 做成满屏发光科幻风；不要用卡通贴纸替代信息层；不要在高缩放时保留地图文字标注抢走注意力；不要让镜头连续快速甩动；不要使用无授权的照片、动画截图与音乐。","migration":[{"field":"config.js → meta","how":"片名（竖排汉字 + 英文）、副标题、时区、总天数、总时长。"},{"field":"config.js → stops","how":"每个地点的名称、代码、汉字、经纬度、海拔、默认场景；填 media 即用真实照片。"},{"field":"config.js → tracks.camera","how":"镜头关键帧；长距离移动在中途加一个低缩放关键帧，形成“飞越”。"},{"field":"config.js → tracks.*","how":"night / clock / day / routes / cards / chapter / flashback / compare / alert / outro 等轨道，改时间即改节奏。"},{"field":"config.js → chapters","how":"每个主题的标签、标题、强调色；会同步到路线、卡片描边与四角框线。"},{"field":"config.js → palette / map","how":"纸色、墨色、夜色与默认强调色；底图样式与 MapLibre 版本。"},{"field":"scenes.js","how":"仅在没有真实照片时使用，可删除；或按示例增加新的程序化场景。"}],"demo":"demos/cases/map-pilgrimage/index.html","research":"docs/research/map-pilgrimage.md","patternIds":["corner-hud","vertical-title-blur","route-draw-marker","day-night-flip","card-expand-fullscreen","chapter-frame","split-compare-stamp","collect-counter","alert-reroute","outro-stat-stack","seekable-timeline","film-grain"],"sources":[{"title":"【眩晕瘫坐 旅游时拍的素材给Opus5.5剪出来是这样】· 哔哩哔哩","url":"https://b23.tv/eBjaN0O","type":"实例 · 影像","note":"用户提供并下载到本地的 151.2 秒 1920×1080 成片；2026-10-14 以 2 秒间隔全片取样，并在 6 处转场以 0.25–0.3 秒间隔逐帧观察。画面署名 @DWTornier。"},{"title":"OpenFreeMap","url":"https://openfreemap.org/","type":"资料 · 底图","note":"免费、无需密钥的矢量瓦片与样式；参考视频右下角同样标注 OpenStreetMap / OpenFreeMap。"},{"title":"MapLibre GL JS","url":"https://maplibre.org/maplibre-gl-js/docs/","type":"资料 · 渲染","note":"地球投影、jumpTo、fill-extrusion、GeoJSON 线图层。"},{"title":"苏轼《饮湖上初晴后雨》","type":"资料 · 公有领域","note":"Demo 回忆段竖排字幕与便签文字。"}],"previewAt":13.6,"preview":"previews/cases/map-pilgrimage.jpg","previewPortrait":null},{"id":"archive-os","order":2,"title":"白色档案终端 · 莱茵式 Analysis OS","subtitle":"CLINICAL ARCHIVE OS / BOOT · ARRAY · DECRYPT","carriers":["console","showcase"],"source":"reference","evidence":"observed","capturedAt":"2026-10-14","tags":["暖灰白","档案阵列","开机序列","滚动编号","解密揭示","空闲呼吸"],"summary":"暖灰白底、细线与紧凑排字，一整片透明档案块组成可浏览的阵列：开机逐字验证身份，切换时选中块抬起并向四周传出波浪，读取时对角线合拢、盖板由磨砂变清晰、正文遮挡条依次退开。","focus":"参考开源项目 RHINE LAB · ANALYSIS OS（MIT）：用 TypeScript + Three.js 复刻《明日方舟》特别映像「莱茵生命：访问」的终端界面，并扩展为 Wallpaper Engine 壁纸。它把影像里的“看”变成可以操作的“用”：每个动作都有方向、余波与回程。Demo 以零依赖的 CSS 3D 重建其定义性机制，品牌与档案内容全部替换为原创。","accent":"#c8742f","background":"#eae5e1","timeline":true,"kit":true,"previewAt":11.8,"energy":[0.15,0.35,0.45,0.5,0.6,0.7,0.55,0.45,0.5,0.55,0.5,0.75,0.8,0.6,0.4,0.35,0.45,0.4,0.3],"rhythm":{"duration":24,"beats":[{"t":0.3,"label":"逐字输入","note":"白场上 ACCESS REQUEST 逐字打出，冒号后停顿，输入完成黑底闪一次后清空。"},{"t":2,"label":"圆环与标志","note":"两个圆环依次绕行描出，随后标志笔画补全，整组左移让出位置。"},{"t":3.3,"label":"身份确认","note":"ID CONFIRMED / REQUEST RECEIVED / START PROCESSING 三行错峰打字。"},{"t":4.6,"label":"授权扫描","note":"黑白双环从画面外收拢，橙色节点绕行，中心方块四帧跳变。"},{"t":5.8,"label":"欢迎","note":"黑底公司名横向擦出，INTERNAL DATABASE 闪现两次。"},{"t":6.7,"label":"阵列入场","note":"启动层缩小、失焦并带轻微色偏退场；阵列从左侧滑入、镜头从近侧视抬高。"},{"t":9.4,"label":"切列","note":"选中块临界阻尼抬起 26px，其余块收到按距离延迟的正弦余波；编号、标题、列名同向滚动 460ms。"},{"t":10.6,"label":"翻阅","note":"同列前后切换，刻度当前位加长；连续输入只显示“当前运动 → 最新目标”。"},{"t":13.8,"label":"读取 · 解密","note":"选中块继续升高、阵列淡出拉近；玻璃检视窗与文档入场，对角线合拢、盖板自上而下转清、遮挡条依次退开。"},{"t":19.2,"label":"返回","note":"详情 250ms 退出，块回落，阵列恢复；停止操作 2.5 秒后开始呼吸起伏。"}]},"layers":[{"name":"氛围层","role":"暖灰白底 + 径向提亮，上下与右侧压浅色遮罩，让阵列在边缘自然消失。"},{"name":"阵列层","role":"5 列 × 16 块的 CSS 3D 档案块（顶面/正面/侧面），抬起、波浪、呼吸都作用在 translateZ。"},{"name":"信息层","role":"品牌三行、系统导航、悬停信息（分类/编号/标题/ACCESS）、选择计数、行列导航、页脚状态与时钟。"},{"name":"详情层","role":"左侧玻璃检视窗（内构 SVG + 磨砂层 + 对角线），右侧档案文档与遮挡条。"},{"name":"启动层","role":"逐字输入、圆环标志、身份确认、授权扫描、欢迎——全部覆盖在白场上，结束后整体失焦退场。"}],"composition":{"color":"暖灰白 #eae5e1 + 近黑墨色 #171713 + 杏金/铜色 #c8742f 作为唯一信号色（选中边、内构环、对角线）；不使用纯白与纯黑大面积。","typography":"几何无衬线：品牌三行用 800/700/300 字重对比与字距；标签 12px 大字距；编号用等宽数字；中文正文 15px 舒适行高。","layout":"左上品牌、右上系统、中右悬停信息、左下计数、中下导航、右下署名；阵列占满画面并从边缘溢出，信息只用细线和点组织。","imagery":"没有照片：所有“图像”都是同一种半透明档案块与它的内构（双环、连接带、标签、螺丝），靠重复和光影建立质感。","motion":"一切运动都“有质量”：临界阻尼抬起、有余波的选择、可接续的滚动编号、2.5 秒后的慢速呼吸；进入与退出时长不对称（入 300–400ms / 出 200–250ms）。","sound":"原项目有逐字输入短音（取自原片）、玻璃交互音与三轨配乐；Demo 默认静音，开启后合成逐字、标志、扫描、欢迎与玻璃轻碰。","rhythm":"开机约 7.6 秒，信息逐层出现；浏览时每次输入 460ms 内完成主要反馈、余波持续约 1 秒；读取解密约 1.6 秒。","coherence":"启动、浏览、读取三个阶段共用同一字体、细线与信号色；每个状态都能从中途反向，保证“操作系统”的可信度。"},"tokens":{"palette":["#eae5e1","#edebe4","#171713","#77756d","#bdb8ad","#c8742f"],"type":"几何无衬线（MiSans/HarmonyOS/Segoe UI 回退）+ 等宽编号","motion":[{"name":"type-tick","value":"每字 45ms（身份行 30–32ms），冒号后停 250–350ms；最短音间隔 24ms"},{"name":"ring-draw","value":"900ms inOutCubic，第二环延迟 450ms"},{"name":"select-lift","value":"临界阻尼速率 4.2，预览抬起 26px，读取抬起 150px"},{"name":"wave","value":"幅度 9px · 角频 7.5 · 衰减 2.6 · 距离延迟 70ms/格 · 距离衰减 1/(1+0.35d)"},{"name":"roll","value":"编号/标题/列名 460ms outCubic，0.35px 运动模糊，方向跟随输入"},{"name":"breathe","value":"空闲 2.5s 后 1.5s 渐入；8s 与 13s 周期以 0.6/0.4 叠加，幅度 4px，相邻块错相"},{"name":"decrypt","value":"对角线 450ms 合拢，停留后 350ms 收束；盖板 1.3s 自上而下转清；遮挡条 420ms、错峰 80ms"},{"name":"modal","value":"入 300–400ms、位移 12px；出 200–250ms、位移 8px，可中途反向"}]},"observations":[{"at":"README · 新版效果","what":"模型与正文同步解密：对角解密线合拢、保持并收束，盖板自上而下由磨砂变清晰；右侧文档的遮挡条随之退开。"},{"at":"README · 循环阵列","what":"五类、每类八份，共 40 份档案；上下翻阅、左右切列均可循环，切回某列保留上次选择；选中抬起与阵列波浪同时开始，标题和编号跟随输入滚动。"},{"at":"DESIGN.md · 档案标题滚动","what":"标题与编号共享 460ms 运动配置，direct 模式直接替换中文、关闭逐字延迟；连续输入从当前运动接续，只显示可见过渡与最新目标。"},{"at":"DESIGN.md · 交互预览","what":"停止操作 2.5 秒后渐入呼吸起伏：8 秒与 13 秒周期叠加，最大单向位移约卡片高度的 2.8%，相邻卡片略微错相；切换、进入详情或减少动态时渐退。"},{"at":"DESIGN.md · 详情与弹窗","what":"检索、收藏、设置弹窗统一 300ms 入场、200ms 退出；入场位移 12px、退出 8px；进入中途关闭时从实际透明度与位移继续。"},{"at":"DESIGN.md · 启动前段","what":"逐字输入、停顿、清空、闪切固定到原片帧点；标志从右上弧线开始绘制、绕左环再补全右环；权限段双环从画面外收拢、橙色节点、四帧缩放跳变；欢迎段黑底横扫与 INTERNAL DATABASE 闪现。"},{"at":"docs/media/archive.jpg","what":"暖灰白底、品牌三行左上、ARCHIVE INDEX / SAVED 右上、FILE NUMBER: X-001 与细线、ARCHIVE / SELECT 01 / 08、行列导航与刻度、POWERED BY 署名、底部 SESSION AUTHORIZED 与时钟。"}],"interaction":["←/→ 切换列（每列记住上次选中），↑/↓ 前后档案，Enter 读取并解密，Esc 返回阵列；屏幕上的箭头与 ACCESS FILE 按钮等效；点击档案块可直接选中。","自动演示由时间轴驱动（可拖动、可逐帧渲染）；任何真实按键或点击切换为实时交互，站点刻度条或重播回到自动演示。","空格播放/暂停；右上角喇叭按钮开启合成音效（默认关闭，页面隐藏自动静音）。","减少动态：不自动播放、停在阵列完整构图，关闭空闲呼吸。"],"useCases":["数据档案 / 资料库浏览","产品与展品陈列台","游戏内终端与图鉴","品牌发布会交互屏","桌面壁纸与工作台"],"avoid":["需要高信息密度表格的后台","高饱和、强情绪的品牌","低性能设备上的大规模 3D"],"constraints":["参考为开源项目 LBEILC/RhineLabUI（MIT）及其 README、DESIGN.md 与截图；《明日方舟》与莱茵生命相关设定权利归鹰角网络，Demo 不使用其标志与名称。","原项目为 Three.js 实时渲染的透射玻璃模型；Demo 用 CSS 3D 方块近似，无物理透射、景深与阴影。","原项目的解密与镜头联动、360° 拆解查看器、画质设置、PWA 与壁纸工作台未复现。","MiSans 字体未随 Demo 分发，按系统字体回退；所有文字 ≥12px。"],"prompt":"用 HTML/CSS/JS（零依赖）实现一个“白色档案终端”：暖灰白底 #eae5e1、墨色 #171713、唯一信号色杏铜 #c8742f，几何无衬线字体。①启动序列（约 7.6s，可跳过、可 seek）：白场上逐字输入“ACCESS REQUEST : ANALYSIS OS”（每字 45ms，冒号后停 350ms，完成后黑底闪一次再清空）→ 两个圆环 900ms 依次绕行描出、标志笔画补全并左移 → 三行身份确认错峰打字 → 黑白双环从画面外收拢、橙色节点绕行、中心方块四帧缩放跳变 → 黑底公司名横向擦出、INTERNAL DATABASE 闪现 → 启动层缩小 4%、模糊 8px 并轻微色偏退场，阵列从左侧滑入、镜头从 74° 抬到 58°。②阵列：CSS 3D（perspective 1700px；rotateX 58° rotateZ -38°）5 列 × 16 块档案（顶/正/侧三个面，正面带标签框与螺丝点），选中块顶边用信号色。③选择：←/→ 切列（记住每列选择）、↑/↓ 前后档案；选中块以临界阻尼（速率 4.2）抬起 26px，其余块收到正弦余波：z += 9·sin(7.5τ)·e^(−2.6τ)/(1+0.35d)，τ = t − t₀ − 0.07·d，d 为行距 + 0.8×列距；编号 X-001、标题、列名、01/08 计数同向滚动 460ms 并带 0.35px 运动模糊，连续输入只显示当前运动到最新目标。④空闲：停止操作 2.5s 后 1.5s 渐入呼吸，8s 与 13s 周期按 0.6/0.4 叠加、幅度 4px、相邻块错相，任何输入立即渐退。⑤读取（Enter）：选中块升至 150px，阵列淡出并拉近左移；左侧玻璃检视窗（内构：双环、铜色环、连接带、标签）入场，两条对角线 450ms 合拢、停留后收束，磨砂层 1.3s 自上而下转清（clip-path），右侧文档的标题、分类、四项元数据、摘要上的黑色遮挡条以 80ms 错峰 420ms 退开；Esc 250ms 退出。⑥HUD：左上品牌三行（800/700/300 字重），右上 ARCHIVE INDEX / SAVED / 声音，中右悬停信息（分类、FILE NUMBER、带方点的细线、标题、ACCESS FILE →），左下 ARCHIVE / SELECT 大号计数，中下行刻度与列导航，右下 POWERED BY，底部 SESSION AUTHORIZED、操作员与时钟。⑦工程：所有状态由“按键事件序列在时刻 t 的推导”得到并写成解析函数，暴露 window.__motion 供 seek；真实输入切换为实时时钟；opacity 加在 3D 面上而不是 preserve-3d 容器；声音默认关闭；减少动态时关闭呼吸；文字 ≥12px。","videoPrompt":"Clinical white sci-fi archive terminal, 1920×1080, 20 seconds. Warm off-white background (#eae5e1), near-black thin typography, a single copper-orange signal color. Opening: on a white screen a monospace-like line types character by character, flashes black, then two thick black rings draw themselves in sequence forming an infinity-like logo; identity lines type in; black and white double rings converge from outside the frame with an orange node orbiting; a black bar sweeps in revealing the company name. The boot layer shrinks, blurs and dissolves into a vast isometric array of translucent ivory archive slabs standing in rows like files in a drawer, filling the frame and fading at the edges. One slab lifts smoothly and a gentle wave ripples outward through neighboring slabs with distance-delayed, damped oscillation; a file number rolls up digit by digit. Then the selected slab rises high, the array fades, a frosted glass panel appears and two diagonal copper lines converge across it; the frosted glass clears from top to bottom revealing double rings inside, while black redaction bars on a document retract one by one. Calm, precise, weighty motion; soft studio light; no lens flares; no neon.","negativePrompt":"不要深色赛博朋克配色或霓虹发光；不要多种强调色；不要让波浪幅度大到块互相穿插；不要每次输入都排队播放所有中间编号；不要无质量的线性动画；不要使用《明日方舟》或莱茵生命的标志与名称。","migration":[{"field":"config.js → brand","how":"品牌三行、操作员、署名。"},{"field":"config.js → columns / files","how":"列名（中英）与每列档案：标题、科室、编目、相关人、状态、摘要；缺省自动生成占位。"},{"field":"config.js → palette","how":"纸色、面板、墨色、灰、细线与唯一信号色。"},{"field":"config.js → timing","how":"启动时长、抬起高度、阻尼速率、波浪参数、滚动时长、呼吸周期与幅度、解密时长。"},{"field":"config.js → autopilot","how":"自动演示的按键脚本（秒）；也是站点刻度条上的节拍。"},{"field":"style.css → .plate","how":"档案块的面色、标签与螺丝装饰；换成产品卡、唱片或展品即可。"}],"demo":"demos/cases/archive-os/index.html","research":"docs/research/archive-os.md","patternIds":["boot-typing","rolling-digits","decrypt-reveal","wave-array","idle-breathing","seekable-timeline"],"sources":[{"title":"LBEILC/RhineLabUI · RHINE LAB · ANALYSIS OS","url":"https://github.com/LBEILC/RhineLabUI","type":"开源 · MIT","note":"2026-10-14 克隆默认分支：README、DESIGN.md（视觉与行为基准）、src 文件结构与 docs/media 截图（2026-09-09 采集）。"},{"title":"【开源】再次震惊瘫坐，GPT6-Astra代码复刻莱茵终端上线Wallpaper Engine · 哔哩哔哩","url":"https://www.bilibili.com/video/BV1e3Y36gEGr","type":"实例 · 影像","note":"用户提供的作者演示视频；本条目的机制描述以仓库文档与截图为准。"},{"title":"RhineLabWallpaper","url":"https://github.com/LBEILC/RhineLabWallpaper","type":"开源","note":"壁纸版独立仓库：工作台、音乐律动、呼吸效果与波纹小游戏。"}],"preview":"previews/cases/archive-os.jpg","previewPortrait":null},{"id":"phantom-battle","order":3,"title":"怪盗动势 · P5 式战斗指令与总攻过场","subtitle":"PHANTOM KINETICS / COMMAND · CUT-IN · ALL-OUT","carriers":["console","video"],"source":"game","evidence":"inferred","capturedAt":"2026-10-14","tags":["红黑白","剪报拼贴字","斜切菜单","切入特写","星形遮罩","冲击字"],"summary":"红、黑、白三色与斜切几何，把战斗菜单本身做成表演：指令环绕角色、选中项放大扭转并抖动影子，命中后冲击字拍出、斜带切入特写、HOLD UP 定格，再以星形遮罩进入总攻与漫画格收尾。","focus":"《女神异闻录5》的界面被视为“菜单即娱乐”的代表：UI 设计师把网站菜单当作灵感来源，字体借鉴性手枪乐队专辑封面的剪报拼贴字。本条目按公开资料与常见设计分析整理其设计语言，并用原创角色、文案与配色比例做成可迁移的战斗过场 Demo；具体帧时长为本地拟合，需以实机录像逐帧核对。","accent":"#d7141a","background":"#0b0b0c","timeline":true,"kit":true,"previewAt":4.4,"energy":[0.45,0.5,0.55,0.85,0.9,0.95,0.8,0.85,0.6,0.9,1,1,0.95,0.9,0.85,0.6,0.4,0.3],"rhythm":{"duration":17.5,"beats":[{"t":0.4,"label":"指令菜单","note":"四个指令环绕角色错峰弹出；光标移动时选中项 160ms snap 放大 1.2、扭转 −6°，黑白反转，白色影子持续抖动。"},{"t":2.6,"label":"选择攻击","note":"菜单收起，旋转准星锁定敌人。"},{"t":3.05,"label":"命中 · WEAK","note":"反色闪 80ms + 屏幕抖动（指数衰减）+ 敌人后坐；WEAK 从 2.6 倍回弹落定、倾斜 −10°。"},{"t":3.9,"label":"1 MORE 切入","note":"黑底红带从右侧 220ms outExpo 切入，速度线流动、眼部特写缓推，剪报字母 30ms 错峰拍入；1.3 秒后继续向左离场。"},{"t":5.4,"label":"HOLD UP","note":"敌人眩晕摇晃，巨大剪报字拍入并伴随抖动。"},{"t":6.5,"label":"询问总攻","note":"画面压暗，ALL-OUT ATTACK 与 GO FOR IT? 提示，等待确认。"},{"t":7.5,"label":"星形遮罩","note":"黑色 16 角星旋转放大吞没画面（inQuad），在总攻画面中缩回（outCubic）。"},{"t":7.9,"label":"总攻","note":"白底上黑色剪影带拖尾冲刺，红色斜切按 0.22 秒节拍闪现，拟声词轮替冲击。"},{"t":10.7,"label":"收尾漫画格","note":"反色闪一帧；红色放射背景旋转，白色斜切漫画格 350ms 推入，标语逐字拍入。"},{"t":14.2,"label":"结算","note":"白色斜切板从左侧 450ms outExpo 滑入，数值行 120ms 错峰。"}]},"layers":[{"name":"背景","role":"红底 + 半色调网点（遮罩渐隐）+ 倾斜黑带 + 极淡斜纹；永远倾斜，没有水平线。"},{"name":"角色与敌人","role":"黑色剪影 + 白描边 + 红色偏移影；敌人带倾斜名牌与血条。"},{"name":"指令层","role":"围绕角色的放射状按钮：几何按键符号 + 粗黑标签；选中态黑白反转与影子抖动。"},{"name":"状态层","role":"右下队伍卡片：斜切黑底、圆形头像、HP/SP 细条。"},{"name":"事件层","role":"准星、反色闪、冲击字、切入斜带、HOLD UP、询问、星形遮罩。"},{"name":"演出场景","role":"总攻（白底黑剪影 + 红切）、收尾漫画格（放射红 + 白格 + 剪报标语）、结算板。"}],"composition":{"color":"只用红 #d7141a、黑 #0b0b0c、白；按键符号与 HP/SP 是唯一的辅助色（绿/粉/蓝），面积极小。高对比带来“叛逆”与“速度”。","typography":"剪报拼贴字：每个字母独立底色、字体（粗黑体/衬线/打字机/窄体）、角度与大小；标签用超粗无衬线；中文用粗黑体。","layout":"所有元素沿对角线组织：倾斜黑带切开画面，菜单按放射角度散布在角色周围，卡片与名牌都带 −3° 到 −8° 的倾斜。","imagery":"剪影化：角色与敌人只有轮廓、面具与眼睛；特写只给眼部；漫画格用放射线与大块黑白。","motion":"快进快停：出现用 outBack/outExpo（150–350ms），离场更快；命中用反色闪 + 指数衰减抖动；所有强调都“拍”进来而不是淡入。","sound":"原作每个光标移动、确认、命中、切入都有短促音效与爵士配乐；Demo 默认静音，开启后合成对应短音。","rhythm":"菜单阶段慢（玩家思考），命中到总攻约 7 秒内连续 6 个高潮事件，间隔 0.8–1.5 秒；总攻内部以 0.22 秒节拍密集冲击，收尾与结算再放慢。","coherence":"同一套“倾斜 + 剪报字 + 红黑白”贯穿菜单、提示、演出与结算，让每个系统界面都像同一张海报的局部。"},"tokens":{"palette":["#d7141a","#8f0b10","#0b0b0c","#ffffff","#9be15d","#ff6fb0","#1fb4ff"],"type":"剪报拼贴（Arial Black / Georgia / Courier / Impact / Bahnschrift 混排）+ 超粗无衬线标签","motion":[{"name":"menu-select","value":"160ms snap：放大 1.18–1.2、扭转 −6°~−7°、右移 26px；影子抖动 ±3px（31/27Hz）"},{"name":"hit","value":"反色闪 60–80ms；抖动 22px·e^(−12t)；目标后坐 40px·e^(−6t)"},{"name":"impact-text","value":"260ms outBack：2.6→1，倾斜 −10°；停留约 0.9s"},{"name":"cut-in","value":"切入 220ms outExpo，停留约 1.3s，离场 220ms inCubic；速度线 1400px/s"},{"name":"ransom-slam","value":"每字 220ms outBack：2.2→1，角度回弹，错峰 30–40ms"},{"name":"shape-wipe","value":"吞没 380ms inQuad → 换场 → 释放 300ms outCubic；旋转 90°/s"},{"name":"frenzy-beat","value":"红切每 220ms 一次，350ms 衰减"}]},"observations":[{"at":"设计访谈 / 报道","what":"UI 设计师从 P3 起把菜单当作“图形娱乐”，并参考网站菜单；P5 菜单字体借鉴性手枪乐队专辑封面的剪报拼贴字（多家媒体转述的访谈内容）。"},{"at":"Mechanics of Magic · Visual Design of Games: Persona 5","what":"暂停菜单悬停项放大并变色，与红黑白主色形成对比；战斗中主要行动（Persona/Item/Guard/Attack）围绕当前角色排布、颜色对应手柄按键；次要行动左下、HP/SP 右下、敌人信息左上。"},{"at":"同上","what":"总攻收尾出现角色漫画格与标语；界面把行动映射到按键，减少多层菜单。"},{"at":"Design Atlas · persona-kinetic（2026-10-07 官网快照）","what":"官网同样以金红黑、剪纸箭头、红色网点与倾斜画面表达都市怪盗风格，可作为网页端的对照。"}],"interaction":["菜单阶段：W/A/S/D 移动选择，Enter 或点击指令开始执行；询问阶段 Enter 确认总攻。","空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个节拍；站内刻度条可拖动。","声音默认关闭；开启后每个事件有对应短音。","减少动态：关闭屏幕抖动与影子抖动，不自动播放。"],"useCases":["游戏战斗/指令界面","直播打赏与高光时刻","综艺/音乐节目包装","潮流品牌发布","活动倒计时与抽奖"],"avoid":["严肃的金融/医疗信息","需要长时间阅读的界面","对闪烁敏感的受众（需关闭闪光）"],"constraints":["证据等级为“公开资料推断”：本会话无法实机录制《女神异闻录5》，所有时长与缓动为本地拟合，请用实机录像逐帧核对（方法见 docs/methodology.md）。","不使用 ATLUS/SEGA 的角色、标志、字体图像、台词与音乐；角色、敌人、标语与队伍名均为原创。","“CURTAIN CALL / 怪盗谢幕”等文案为原创，不复用原作结算台词。","反色闪与抖动存在光敏风险：减少动态时关闭，正式作品建议提供关闭选项。"],"prompt":"做一段 P5 式“战斗指令 + 总攻过场”（HTML/CSS/JS，可 seek，约 17 秒）：只用红 #d7141a、黑 #0b0b0c、白，背景是红底 + 半色调网点 + 旋转 −14° 的黑色斜带。①指令：四个按钮按角度环绕黑色剪影角色（白描边 + 红色偏移影），每个按钮是斜切多边形白底 + 黑色偏移影子 + 几何按键符号（△○×□）+ 超粗标签；选中项 160ms snap 放大 1.2、扭转 −6°、黑白反转，白影子以 31/27Hz 抖动 ±3px；右下是斜切黑底的队伍 HP/SP 卡片。②选择攻击 → 旋转准星锁定敌人 → 命中：差值混合反色闪 80ms、屏幕抖动 22px·e^(−12t)、敌人后坐；WEAK 冲击字（白字黑描边 + 黑色硬投影）从 2.6 倍 outBack 落定并倾斜 −10°。③1 MORE：旋转 −8° 的黑带内嵌红带，从右 220ms outExpo 切入，内有横向流动速度线与眼部特写缓推，剪报字（每个字母独立底色/字体/角度/大小，固定种子）以 30ms 错峰从 2.2 倍拍入，1.3 秒后整条向左离场。④HOLD UP 巨型剪报字 + 敌人眩晕；⑤压暗询问 ALL-OUT ATTACK / GO FOR IT?；⑥黑色 16 角星旋转放大吞没（380ms inQuad）后在白底总攻画面中缩回：黑色剪影带拖尾冲刺，红色斜切按 0.22 秒节拍闪现，拟声词轮替；⑦反色一帧进入收尾：红色放射背景旋转，白色斜切漫画格推入，原创标语逐字拍入；⑧结算：白色斜切板从左滑入，数值行 120ms 错峰。所有动画是时间 t 的纯函数；WASD/Enter 可交互；声音默认关闭；prefers-reduced-motion 关闭抖动与闪光。","videoPrompt":"Stylish JRPG battle UI cutscene in a red, black and white palette, 1920×1080, 17 seconds, inspired by rebellious punk collage design (original characters only). A red background with halftone dots and a tilted black slab; a black silhouette hero with a white outline and red offset shadow stands among four tilted command plates (triangle, circle, cross, square glyphs). The cursor snaps between commands: the selected plate enlarges, twists and inverts to black with a jittering white shadow. Attack: a spinning reticle locks on a spiky masked enemy, a hard inverted flash and camera shake, the word \"WEAK\" slams in tilted with thick black outline. A diagonal black-and-red band slices in from the right with streaking speed lines and a close-up of narrow eyes, while ransom-note letters (each a different font, color block and angle) stamp in one by one reading \"1 MORE!\". \"HOLD UP!\" stamps across the screen. A black 16-point star spins outward to swallow the frame, then shrinks to reveal a white stage where black silhouettes dash with motion trails and red diagonal slashes flash on the beat. A finishing comic panel slides in over a rotating red sunburst with a collage tagline. Ends on a white slanted results plate sliding in from the left. Snappy, high-contrast, jazz-funk energy.","negativePrompt":"不要使用原作角色、标志、字体图像、台词或音乐；不要出现水平垂直的“正经”版式；不要渐变光晕、毛玻璃或霓虹；不要慢速淡入；不要每个字母同一种样式；不要让抖动与闪光在减少动态时出现。","migration":[{"field":"config.js → palette","how":"主红、深红、黑、白与按键辅助色。"},{"field":"config.js → commands","how":"指令标签、中文、按键、几何符号与环绕角度（度）。"},{"field":"config.js → party / enemy","how":"队伍名称、HP/SP、头像色；敌人名称与等级。"},{"field":"config.js → text","how":"冲击字、切入字、HOLD UP、询问、收尾标语与结算行。"},{"field":"config.js → beats","how":"每个事件的时刻：调这里即可改整场战斗的节奏。"},{"field":"index.html → svg","how":"角色、敌人与漫画格剪影；替换为你的角色立绘或剪影。"}],"demo":"demos/cases/phantom-battle/index.html","research":"docs/research/phantom-battle.md","patternIds":["skew-menu","cutin-slash","ransom-type","impact-pop","shape-wipe"],"sources":[{"title":"Mechanics of Magic · Visual Design of Games: Persona 5","url":"https://mechanicsofmagic.com/2022/04/23/visual-design-of-games-persona-5/","type":"资料 · 分析","note":"暂停菜单的放大与变色、战斗行动环绕角色与按键配色、信息分区（核心/支撑/附加）。"},{"title":"GameSpot · Persona 5’s Menus Continue to Look Stunning","url":"https://www.gamespot.com/articles/persona-5s-menus-continue-to-look-stunning/1100-6439532/","type":"资料 · 报道","note":"早期预告与开发访谈中的菜单与胜利画面过渡。"},{"title":"DT Next · Exuberant video game menus","url":"https://www.dtnext.in/amp/story/edit/exuberant-video-game-menus-designed-with-da-vinci-in-mind-807823","type":"资料 · 报道","note":"转述设计师把菜单视为“图形娱乐”、参考网站菜单与剪报拼贴字封面的说法。"},{"title":"Design Atlas · Persona 5 Royal 黑金角色拼贴","url":"https://mibxr-design-atlas.mibxranime.chatgpt.site/cases.html#style/persona-kinetic","type":"实例 · 姊妹库","note":"官网（2026-10-07 快照）的网页端设计语言对照。"}],"preview":"previews/cases/phantom-battle.jpg","previewPortrait":null},{"id":"industrial-protocol","order":4,"title":"工业协议 · 终末地式设施操作台","subtitle":"INDUSTRIAL PROTOCOL / PANEL · FLOW · DEPLOY","carriers":["console","showcase"],"source":"game","evidence":"inferred","capturedAt":"2026-10-14","tags":["工业机能","安全黄","切角面板","危险条纹","字符解码","长按确认"],"summary":"米灰工业表面、石墨黑与安全黄，切角面板、注册标记、刻度与危险条纹构成“管理员终端”；分段加载后各区块以吸附缓动就位，产线物料沿传送带流动，设备蓝图逐线描出，部署需按住确认，换页用一条发光扫描线。","focus":"《明日方舟：终末地》以“工业机能 + 未来科幻”的界面建立玩家“管理员”的身份：三角形元素与工业徽章贯穿系统界面，Logo 衍生图形在终端、配装站、角色面板反复出现；集成工业（工厂）系统让玩家在菜单里规划产线。本条目整理公开评析中的设计语言，用原创设施、产线与干员名称做成可迁移的操作台 Demo；实机动效参数待录像核验。","accent":"#ffd400","background":"#e6e6e1","timeline":true,"kit":true,"previewAt":8.4,"energy":[0.3,0.45,0.6,0.5,0.45,0.55,0.6,0.75,0.85,0.6,0.65,0.55,0.6,0.55,0.5,0.4,0.35],"rhythm":{"duration":17,"beats":[{"t":0.2,"label":"分段加载","note":"三角徽记 + 标题字符解码；24 段进度条带随机跳变，当前段为安全黄。"},{"t":2.2,"label":"界面装配","note":"加载层自下而上裁切退场；顶栏、侧栏、内容区、详情区、底栏以 420ms snap 缓动从各自边缘就位，资源数字计数。"},{"t":3,"label":"产线运转","note":"物料方块沿传送带流动，带纹同速推进，节点指示灯闪烁。"},{"t":4.6,"label":"选择设备","note":"节点四角黄色括号回弹出现；右侧名称解码、蓝图逐线描出、三项分段条依次填充。"},{"t":6.4,"label":"按住部署","note":"按住期间黄色从左填满（1.2s），松开过早回落；满格锁定为完成态。"},{"t":7.8,"label":"部署完成","note":"绿色描边印章倾斜盖下，设备产量提升、相关传送带加速，日志更新。"},{"t":9.4,"label":"扫描线换页","note":"发光黄线从左扫到右：线左是新页、线右是旧页；新页标题解码、卡片 snap 错峰上浮。"},{"t":12.2,"label":"仓储","note":"同一扫描线换页；行数据从左侧错峰滑入。"},{"t":14.6,"label":"回到产线","note":"已部署状态保留，产线继续以加速运转。"}]},"layers":[{"name":"底层","role":"米灰底 + 40px 细网格，像工程图纸。"},{"name":"框架层","role":"石墨黑顶栏（右下切角）、侧栏按钮（右下切角）、内容区与详情区（对角切角 + 注册标记）、底栏（危险条纹 + 日志）。"},{"name":"内容层","role":"产线节点图（SVG）/ 干员卡片 / 仓储表格；换页时由扫描线裁切。"},{"name":"详情层","role":"设备名称、深色蓝图（浅蓝线框 + 虚线网格）、分段指标条、按住部署按钮与印章。"},{"name":"启动层","role":"三角徽记、解码标题、分段进度条与百分比。"}],"composition":{"color":"米灰 #e6e6e1 / 面板 #f4f4f0 / 石墨 #1d1f22 构成 90% 面积；安全黄 #ffd400 只用于“当前、警示、进行中”；完成用绿色，蓝图用浅蓝线。","typography":"DIN 类窄体（Bahnschrift）做标题与数值、等宽字体做编码与日志、中文黑体做名称；大量大写英文编码 + 中文名称的双语标注。","layout":"严格的模块化网格：顶栏 / 左侧栏 / 中央内容 / 右侧详情 / 底栏；每个模块都有切角与标记，像设备上的铭牌。","imagery":"无照片：设备以几何图标与线框蓝图表现，干员卡片以深色块 + 几何暗纹 + 稀有度条表现。","motion":"机械、准确：snap 缓动（快进硬停）、错峰装配、字符解码、匀速传送带；没有弹性夸张，唯一的回弹留给“完成”印章与选中括号。","sound":"原作有系统确认音与工业环境音；Demo 默认静音，开启后合成加载滴答、装配气流、选择、蓄力上扬与完成双音。","rhythm":"启动 2.4s 内完成加载与装配；之后以“持续运转（传送带）+ 离散事件（选择/部署/换页）”交替，离散事件间隔 1.5–3 秒。","coherence":"所有模块共享切角语言、注册标记与安全黄的单一语义，切换模块时只有内容变化，框架保持不动——“同一台设备上的不同屏幕”。"},"tokens":{"palette":["#e6e6e1","#f4f4f0","#1d1f22","#6b6e70","#c9cbc6","#ffd400","#2fbf71","#9fd3ff"],"type":"Bahnschrift / DIN 类窄体 + 等宽编码 + 中文黑体","motion":[{"name":"snap","value":"cubic-bezier(.2,.9,.1,1)：装配 420ms、页签指示 350ms、卡片 320ms"},{"name":"assemble-stagger","value":"顶栏 → 侧栏（60ms/项）→ 内容 → 详情 → 底栏，约 0.1s 递进"},{"name":"scramble","value":"24fps 随机字符刷新，阈值 = 位置×0.7 + 随机×0.3，时长 0.6–1.2s"},{"name":"conveyor","value":"物料 90px/s（部署后 150px/s），每条带 4 个，带纹同速"},{"name":"blueprint","value":"8 条线框各 450ms inOutCubic，错峰 70ms"},{"name":"hold","value":"1.2s 线性填充，松开 300ms 回落；完成印章 350ms outBack"},{"name":"scanline","value":"500ms inOutQuart，3px 黄线 + 外发光"}]},"observations":[{"at":"17173 评析 · 工业风视觉语言","what":"界面中的核心符号是三角形元素与工业徽章；Logo 及衍生图形在终端、配装站、角色信息面板等关键界面反复复用，强化“管理员”身份认同。"},{"at":"同上 · 菜单与多平台","what":"PC 端承载更密集的信息与快捷操作栏，移动端缩放重组并把关键按钮放在拇指区域；手柄与键鼠侧重焦点切换与快捷键。"},{"at":"GameWith / 攻略 · 集成工业","what":"工厂规划在 AIC Plan 界面与建造模式中进行，包含模拟、研究升级与蓝图（Schematics）导入导出。"},{"at":"Design Atlas · endfield-industrial（官网八章研究）","what":"官网同样采用白底工业档案、点云射线与分层切换，可作为网页端对照。"}],"interaction":["点击顶栏页签切换模块（扫描线换页），点击产线节点选择设备，按住 DEPLOY（或聚焦后按住空格/回车）1.2 秒部署。","自动演示由时间轴驱动，任何点击切到实时交互；站内刻度条或重播回到自动演示。","声音默认关闭；减少动态时不自动播放，停在部署完成的完整构图。","SVG 内的文字会按画布实际缩放换算字号，保证最终渲染 ≥12px。"],"useCases":["工业/能源/物流监控台","游戏内建造与管理界面","B 端设备管理后台的品牌化外观","展会设备展示屏","科幻影视 FUI"],"avoid":["温暖亲和的消费品牌","以图片为主的内容浏览","需要高信息密度表格且不允许装饰的严肃系统"],"constraints":["证据等级为“公开资料推断”：未实机录制《明日方舟：终末地》，动效时长为本地拟合；请按 docs/methodology.md 用实机录像核验后更新。","不使用鹰角网络/GRYPHLINE 的标志、角色、术语（如源石、AIC 等）与美术；设施、干员与资源名称均为原创。","产线图为示意，不包含真实游戏的配方与数值。"],"prompt":"做一个“工业协议”风格的设施操作台（HTML/CSS/JS，可 seek）：米灰底 #e6e6e1 + 40px 细网格，面板 #f4f4f0，石墨 #1d1f22，安全黄 #ffd400 只表示“当前/进行中/警示”，完成用绿色。字体：Bahnschrift/DIN 类窄体 + 等宽编码 + 中文黑体。布局：石墨黑顶栏（三角徽记 + 终端名 + 4 个页签 + 资源计数，右下切角，当前页签下方 4px 黄色指示条以 350ms snap 移动）、左侧子菜单（右下切角，当前项反黑 + 右侧黄条）、中央内容（对角切角）、右侧详情（对角切角 + 四角十字注册标记）、底栏（危险斜纹 + 坐标 + 滚动日志 + 时钟）。①启动：三角徽记 + 标题字符解码（24fps 随机字符，按位置逐个解出）+ 24 段进度条（当前段黄色，带随机跳变）→ 加载层自下而上裁切退场，各区块以 cubic-bezier(.2,.9,.1,1) 420ms 从各自边缘错峰装配，资源数字计数。②产线：SVG 节点图（切角白盒、几何图标、编码、名称、OUTPUT/min、闪烁指示灯），节点间是带圆角的正交传送带（灰色粗底 + 黑色虚线带纹按速度推进），物料方块按 (t×速度/长度 + i/数量) mod 1 沿路径取点。③选择设备：四角黄色括号 outBack 回弹；右侧名称解码、深色蓝图 8 条浅蓝线框（pathLength=1）错峰 70ms 描出、三项 10 格分段条依次填充。④按住部署：按住时黄色从左线性填满 1.2s，松开过早 300ms 回落，满格锁定为 DEPLOYED 并盖下倾斜绿色印章，相关产线加速。⑤换页：3px 黄色发光扫描线 500ms inOutQuart 从左扫到右，线左新页、线右旧页（两侧 clip-path），新页标题解码、卡片 snap 错峰上浮。SVG 文字按实际缩放换算保证 ≥12px；声音默认关闭；减少动态停在完成态。","videoPrompt":"Industrial sci-fi management terminal UI, 1920×1080, 16 seconds. Off-white industrial panels with chamfered 45-degree corners, graphite black header bar, a single safety-yellow accent, crosshair registration marks, tick rulers and yellow-black hazard stripes, a thin engineering grid background. A triangle emblem appears and a monospace title decodes from random characters while a 24-segment progress bar fills. The loader slices away upward and UI modules snap into place from their edges with mechanical precision. A production-line node graph runs: small black square items flow along orthogonal conveyor belts between machine nodes with blinking green lamps. A machine is selected with yellow corner brackets popping in; on the right a dark blueprint panel draws light-blue wireframe lines one by one and segmented meters fill. A long-press button fills with yellow from left to right and a green \"DEPLOYED\" stamp slams down at an angle. Then a glowing yellow scanline sweeps across the content area revealing a new page of dark operator cards. Precise, mechanical, calm; no glow overload; no neon.","negativePrompt":"不要赛博朋克霓虹与紫粉渐变；不要圆润的消费级卡片与大阴影；不要让黄色泛滥成背景色；不要弹性夸张的动画；不要使用原作的标志、角色、术语与美术。","migration":[{"field":"config.js → brand / palette","how":"终端名称、站点代码、版本号；纸色、面板、石墨、灰、细线、安全黄、警示与完成色。"},{"field":"config.js → tabs","how":"模块页签（英文 + 中文）与每个模块的子菜单。"},{"field":"config.js → machines / links","how":"产线节点（坐标、编码、名称、产量、图标）与连接关系，传送带路径自动生成。"},{"field":"config.js → operators / resources","how":"卡片内容与顶栏资源计数。"},{"field":"config.js → holdDuration / autopilot","how":"长按确认时长；自动演示事件（选择、按住、换页）的时刻。"},{"field":"style.css → --cut","how":"切角尺寸；改成 0 即得到直角版本。"}],"demo":"demos/cases/industrial-protocol/index.html","research":"docs/research/industrial-protocol.md","patternIds":["chamfer-panel","text-scramble","conveyor-flow","hold-confirm","scanline-wipe"],"sources":[{"title":"17173 · 明日方舟：终末地 评析专题","url":"https://news.17173.com/z/arknights2026/content/01202026/181744280.shtml","type":"资料 · 评析","note":"工业机能美学、三角形元素与工业徽章、Logo 衍生图形复用、多平台布局适配。"},{"title":"GameWith · Arknights: Endfield 集成工业指南","url":"https://gamewith.net/akendfield/72372","type":"资料 · 攻略","note":"工厂规划界面入口、模拟与研究升级、蓝图导入流程。"},{"title":"Design Atlas · 终末地 白底工业档案","url":"https://mibxr-design-atlas.mibxranime.chatgpt.site/cases.html#style/endfield-industrial","type":"实例 · 姊妹库","note":"官网研究（网页端设计语言）对照。"}],"preview":"previews/cases/industrial-protocol.jpg","previewPortrait":null},{"id":"broadcast-pack","order":5,"title":"赛事转播图形包 · 踩拍的信息层","subtitle":"BROADCAST PACKAGE / STINGER · BUG · LOWER THIRD · STATS","carriers":["video","console"],"source":"original","evidence":"original","capturedAt":"2026-10-14","tags":["转播包装","120 BPM","斜切色带","比分角标","下三分之一","数据对比"],"summary":"电竞/体育直播的一整套图形包：色带转场、比分角标、三段式下三分之一、数据对比条、得分强调、回放框、滚动新闻与冠军卡——所有出入场都按 120 BPM 的拍子写，转场永远落在拍点上。","focus":"转播图形的核心不是“好看的条”，而是“可预期的节奏”：观众在 30 秒内会看到 8–10 个图形元素，如果每个都踩在音乐拍点上、并且遵循同一套入场语法（色条→底板→文字），信息就会显得专业、可信而不吵。这个原创设计语言把节拍写进配置，改 BPM 即可整体重新对齐。","accent":"#c6ff3d","background":"#0a1230","timeline":true,"kit":true,"previewAt":10,"energy":[0.9,0.7,0.4,0.5,0.55,0.5,0.6,0.65,0.6,0.95,0.7,0.85,0.6,0.5,0.45,0.5,0.55,0.9,0.85,0.6,0.4],"rhythm":{"duration":24,"bpm":120,"beats":[{"t":0,"label":"开场色带","note":"5 条斜色带（青柠/青/白/品红/深蓝）错峰 70ms 横扫 2 拍，标志字母斜切滑入。"},{"t":2,"label":"比分角标","note":"第 4 拍横向展开（snap 400ms），赛事条 + 队名 + 比分。"},{"t":4,"label":"下三分之一","note":"第 8 拍：色条 200ms 长出 → 底板 350ms 擦出 → 三行文字 80ms 错峰上浮；第 15 拍倒序离场。"},{"t":8,"label":"数据对比","note":"第 16 拍：标题下落，每半拍一行从中线展开，条形向两侧生长并计数。"},{"t":12,"label":"得分","note":"第 24 拍：角标闪光、比分滚动、巨型斜体字回弹、场景轻微震动。"},{"t":14,"label":"回放转场","note":"第 28 拍：色带转场遮住硬切；进入品红回放框、0.5× 慢放、轨迹与半速时间码。"},{"t":18,"label":"回到直播","note":"第 36 拍色带转场；第 37 拍底部滚动新闻条上浮。"},{"t":21,"label":"冠军卡","note":"第 42 拍：冠军名回弹放大、比分胶囊弹出、彩带抛洒。"},{"t":23,"label":"结尾色带","note":"第 46 拍：色带 + 标志收尾。"}]},"layers":[{"name":"场景","role":"深蓝竞技场：灯束、透视网格地板、观众光点；回放时降饱和并减速。"},{"name":"常驻层","role":"左上比分角标、底部滚动新闻、右下拍点指示灯。"},{"name":"事件层","role":"下三分之一、数据对比、得分大字、冠军卡——一次只出现一个。"},{"name":"框架层","role":"回放框（品红描边 + 标签 + 倍速 + 时间码）。"},{"name":"转场层","role":"色带 stinger 与品牌标志，遮住场景硬切。"}],"composition":{"color":"深蓝 #0a1230 做底与底板；青柠 #c6ff3d 为主队与系统强调；青 #29d3ff 为客队；品红 #ff2e88 只用于“直播/回放”等状态；白色用于正文。","typography":"DIN 类窄体（Bahnschrift）+ 斜体做名字与大字，等宽字体做标签与时间码；大写、宽字距的小标签与超大斜体数字形成对比。","layout":"常驻元素贴边（左上角标、底部新闻），事件元素在左下（人物条）或中央（数据、得分、冠军）；所有图形都带 −12° 到 −18° 的斜切。","imagery":"没有照片：竞技场由渐变、锥形光束、透视网格与光点构成，保证图形层永远是主角。","motion":"统一的入场语法：先出“色”（色条/色带）、再出“底”（底板擦出）、最后出“字”（上浮/计数）；离场倒序且更快（约入场的 60%）。","sound":"开启声音后：每拍底鼓、反拍镲片、转场呼啸、得分三和弦、冠军五和弦——帮助理解“踩拍”。","rhythm":"120 BPM（一拍 0.5s）；元素入场在整拍，离场提前 1 拍开始；转场长度 2 拍；每 4–8 拍一个新事件。","coherence":"每个元素都来自同一套斜切几何、同一组颜色角色和同一个节拍网格，因此即使信息很多，也像同一首曲子的不同乐句。"},"tokens":{"palette":["#0a1230","#050a1c","#c6ff3d","#29d3ff","#ff2e88","#ffffff"],"type":"Bahnschrift / DIN 窄体斜体 + 等宽标签","motion":[{"name":"beat","value":"120 BPM = 0.5s；所有入场写成拍号"},{"name":"stinger","value":"5 条 34% 宽、−18° 斜切色带，错峰 70ms，2 拍 inOutCubic 横扫"},{"name":"bug","value":"400ms snap 横向展开；比分滚动 400ms"},{"name":"lower-third","value":"色条 200ms → 底板 350ms snap → 文字 300ms，错峰 80ms；离场 140–220ms"},{"name":"stats","value":"每半拍一行；条形 900ms outQuart 从中线生长并计数"},{"name":"point","value":"250ms outBack 1.6→1，−10° 斜切；震动 10px·e^(−8t)"},{"name":"replay","value":"场景速度 ×0.5、降饱和；品红框 + 标签闪烁 2Hz"}]},"interaction":["空格播放/暂停；←/→ 跳 1 秒；Shift+←/→ 跳到上/下一个节拍标记；站内刻度条显示每个图形的出场拍。","右下拍点灯每拍闪一次、小节首拍更大，便于对照“踩拍”。","开启声音后有底鼓/镲片节拍与转场音效。","减少动态：关闭场景震动与彩带，不自动播放。"],"useCases":["电竞/体育直播包装","发布会与年会直播","综艺与节目包装","直播间信息条","数据播报短视频"],"avoid":["安静的纪录片与访谈","需要长时间阅读的信息"],"constraints":["原创设计语言：赛事名、队伍、选手与数据均为虚构。","回放段仅以轨迹示意，实际节目应替换为真实回放素材。","所有文字 ≥12px；1920×1080 成片下标签为 12–14px。"],"prompt":"做一套 24 秒的电竞转播图形包（HTML/CSS/JS，可 seek），120 BPM，所有元素按拍号出入场：配色深蓝 #0a1230 / 青柠 #c6ff3d（主队与系统）/ 青 #29d3ff（客队）/ 品红 #ff2e88（直播与回放状态）/ 白；字体 Bahnschrift 窄体斜体 + 等宽标签；所有图形带 −12°~−18° 斜切。背景是深蓝竞技场（锥形光束、透视网格地板、观众光点）。①第 0 拍色带转场：5 条 34% 宽的斜色带错峰 70ms 在 2 拍内横扫，品牌字母斜切滑入；②第 4 拍左上比分角标 400ms snap 横向展开（赛事条 + 队名色条 + 比分）；③第 8 拍下三分之一：青柠色条 200ms 从下长出 → 深蓝底板 350ms 从左擦出（右端斜切）→ 标签/姓名/职位 80ms 错峰上浮；第 15 拍倒序离场；④第 16 拍数据对比：青柠标题条下落，三行数据每半拍一行从中线展开，左右条形 900ms outQuart 向两侧生长并计数；⑤第 24 拍得分：角标青柠闪烁、比分滚动、巨型斜体“POINT · 队名”250ms outBack 落定、场景震动；⑥第 28 拍色带转场进入回放：品红描边框、REPLAY 标签 2Hz 闪、0.5×、轨迹以半速划过、时间码半速；第 36 拍色带回到直播；⑦第 37 拍底部滚动新闻条上浮；⑧第 42 拍冠军卡：名字回弹、比分胶囊、彩带；⑨第 46 拍色带 + 标志收尾。右下拍点灯每拍闪一次。声音默认关闭；减少动态关闭震动与彩带。","videoPrompt":"Esports broadcast graphics package, 1920×1080, 24 seconds at 120 BPM, every graphic landing on the beat. Deep navy arena with cone light beams, a glowing perspective grid floor and twinkling crowd dots. Opens with five slanted color bars (lime, cyan, white, magenta, navy) sweeping across the screen in a staggered stinger, revealing an italic condensed logo. A slanted score bug snaps open top-left. A lower third builds in three stages: a lime bar grows, a navy plate wipes out with a slanted edge, then name and role rise in. A match-stats panel unfolds row by row from the center with bars growing outward and numbers counting up. A big italic lime \"POINT\" slams in with a flash on the score bug. A stinger hides the cut to a magenta-framed slow-motion replay with a glowing lime trajectory and half-speed timecode. A news ticker slides up; a champion card bursts in with confetti. Crisp, energetic, high-contrast, perfectly rhythmic.","negativePrompt":"不要让多个事件图形同时出现；不要软绵绵的淡入淡出；不要让转场时长与拍子不一致；不要过多颜色角色；不要真实赛事的商标与选手。","migration":[{"field":"config.js → bpm / beats","how":"改 BPM 即整体变速；beats 中每个元素的出场拍号决定节奏结构。"},{"field":"config.js → event / teams","how":"赛事名、阶段、场馆；队伍代码、名称、颜色与比分变化。"},{"field":"config.js → lowerThird / stats / ticker","how":"人物条三行、数据对比行（可带小数）、滚动新闻。"},{"field":"config.js → palette","how":"底色、主客队色与状态色（直播/回放）。"},{"field":"style.css","how":"斜切角度（skewX）、色带宽度、字体与圆角。"}],"demo":"demos/cases/broadcast-pack/index.html","research":"docs/research/broadcast-pack.md","patternIds":["lower-third","stinger-bars","seekable-timeline","beat-clock"],"sources":[{"title":"原创设计语言 · Motion Atlas","type":"原创","note":"基于电视与直播图形包的通用结构（角标、下三分之一、转场 stinger、数据条）设计；所有名称与数据虚构。"}],"preview":"previews/cases/broadcast-pack.jpg","previewPortrait":null},{"id":"beat-lyric","order":6,"title":"节拍动态字幕 · Kinetic Lyric MV","subtitle":"ON THE ONE / 96 BPM KINETIC TYPOGRAPHY","carriers":["video"],"source":"original","evidence":"original","capturedAt":"2026-10-14","tags":["节拍同步","动态字体","硬切","遮罩上升","堆叠网格","Drop"],"summary":"把歌词写成“拍号表”：词在拍上硬切出现、反拍轻轻上弹、军鼓拍条纹闪、每段换一整块颜色、Build 段八分音符叠字加速、Drop 每拍换色并震动——画面本身就是一份可视化的节拍器。","focus":"“韵律感”的关键是：画面的每次变化都对齐到一个可感知的时间网格（拍、半拍、小节），并且不同层级的变化用不同频率——词按拍、颜色按段、闪光按军鼓、镜头按底鼓。Demo 内置合成鼓点，开启声音后用前瞻调度与画面同拍，方便直接感受“对齐”带来的愉悦。","accent":"#ff4d2e","background":"#111214","timeline":true,"kit":true,"previewAt":13.9,"energy":[0.25,0.3,0.55,0.6,0.5,0.55,0.6,0.65,0.7,0.75,0.85,0.95,1,1,0.95,0.9,0.6,0.45,0.3],"rhythm":{"duration":31.2,"bpm":96,"beats":[{"t":0,"label":"倒数","note":"1·2·3·4 每拍一个数字，等宽体，1.4→1 落定后在 60% 拍处淡出。"},{"t":2.5,"label":"WE MOVE ON THE ONE","note":"每拍一个词硬切出现，1.5→1（120ms outExpo），反拍上弹 2%。"},{"t":5,"label":"中文遮罩上升","note":"红底；“城市 / 在拍子里 / 醒来 / 每一步 / 都算数”从基线下方上升，按 hold 拍数停留后向上离场。"},{"t":10,"label":"堆叠网格","note":"蓝底；8 个格子逐拍点亮一个词，第 20 拍起隔格反色闪烁。"},{"t":15,"label":"Build","note":"米白底；“UP”按八分音符叠加放大、留下残影，条纹闪随进度加密，军鼓变成滚奏。"},{"t":20,"label":"Drop","note":"巨型 DROP 铺满，每拍换色、底鼓震动与纵向拉伸。"},{"t":25,"label":"Outro","note":"“STAY ON THE ONE”逐拍，第 44 拍进入结尾卡。"}]},"layers":[{"name":"色场","role":"整块纯色背景；段落开始时新色块 350ms 从左擦入，Drop 每拍换色。"},{"name":"闪光层","role":"军鼓拍的 100° 斜条纹（difference 混合），Build 段随进度加密。"},{"name":"镜头","role":"包住文字层的缩放与震动：每拍缩放脉冲 2.2%（Drop 6% + 震动）。"},{"name":"文字层","role":"倒数、拍入、遮罩上升、堆叠网格、叠字、巨型字，各段一种语法。"},{"name":"HUD","role":"标题 + 段名、小节/拍计数 + 四格拍点、底部频谱条。"}],"composition":{"color":"四种纯色轮换：炭黑 #111214、信号红 #ff4d2e、电蓝 #2b59ff、米白 #f5f0e6；每段只用两色（底 + 字），强调色只在拍点灯与小元素上。","typography":"超粗窄体大写（Bahnschrift 75% 宽）做英文；超粗黑体做中文；等宽体做倒数与 HUD。字号以视口宽度计，单词永远占满画面主体。","layout":"中心构图为主，Stack 段改为 2×4 网格，Build 段散点叠加——用版式变化标记段落。","imagery":"没有图像：颜色、字形与节拍就是全部画面。","motion":"硬切优先：词在拍上直接出现（不淡入），只用 120ms 的“落定”缩放；反拍的小上弹与每拍镜头脉冲提供持续律动。","sound":"合成四拍底鼓、2/4 拍军鼓、反拍镲片与每拍低音；Build 段军鼓滚奏，Drop 段每拍底鼓 + 开镲。","rhythm":"词 = 拍；闪光 = 军鼓；镜头 = 底鼓；颜色 = 段落（2 小节）；八分音符只在 Build 使用——层级分明，避免“全都在动”。","coherence":"所有视觉事件都是同一个拍号表的不同读法，改 BPM 一处即可整体同步。"},"tokens":{"palette":["#111214","#ff4d2e","#2b59ff","#f5f0e6","#ffd23f"],"type":"Bahnschrift 窄体 800 + 中文黑体 900 + 等宽 HUD","motion":[{"name":"beat","value":"96 BPM = 625ms；十六分音符 156ms"},{"name":"slam","value":"出现瞬间 1.5→1，120ms outExpo；hold 拍后硬切"},{"name":"offbeat","value":"+0.5 拍上弹 2%，e^(−10·Δ) 回落"},{"name":"rise","value":"遮罩内 250ms outCubic 上升，200ms inCubic 离场"},{"name":"cam-pulse","value":"每拍 1 + 0.022·e^(−8·frac)（Drop 0.06 + 14px 震动）"},{"name":"section-wipe","value":"新色块 350ms inOutQuart 从左擦入"},{"name":"audio","value":"前瞻 120ms 调度到 AudioContext"}]},"interaction":["空格播放/暂停；←/→ 跳 1 秒；Shift+←/→ 跳段落；站内刻度条按段落标记。","开启声音：合成鼓点与画面同拍（前瞻调度，拖动后自动重排）。","减少动态：关闭镜头缩放、震动与条纹闪，不自动播放。"],"useCases":["歌词 MV / Lyric Video","短视频卡点","品牌口号影片","发布会开场","演出 VJ 素材"],"avoid":["光敏人群（需关闭闪光与 Drop 换色）","需要细读的长句"],"constraints":["原创歌词与合成鼓点，无真实音乐授权问题；接入真实歌曲时需按歌曲 BPM 与拍点重写 lyrics 表。","Drop 段每拍换色属于高强度闪烁，正式发布应提供关闭选项。"],"prompt":"做一支 30 秒的节拍动态字幕 MV（HTML/CSS/JS，可 seek），96 BPM、12 小节：把歌词写成拍号表 {beat, text, style, hold}，所有视觉事件都换算成拍。①倒数：1·2·3·4 每拍一个等宽数字；②拍入（slam）：英文大写超粗窄体占满画面，每拍硬切出现，120ms outExpo 从 1.5 倍落定、−3° 回正，反拍上弹 2%；③遮罩上升（rise）：中文超粗黑体在 overflow:hidden 容器中 250ms 从下方升起，按 hold 拍停留后向上离场；④堆叠网格（stack）：2×4 描边格子逐拍点亮一个词，第 5 小节起隔格反色；⑤Build：“UP”按八分音符叠加，每次放大 12%、旋转、散点位置，旧的留下衰减残影，斜条纹闪随进度加密；⑥Drop：巨型词铺满，每拍在四色间轮换底与字，底鼓震动 + 纵向拉伸；⑦结尾卡。配色四种纯色轮换（炭黑/信号红/电蓝/米白），每段新色块 350ms 从左擦入；镜头每拍缩放脉冲 2.2%；军鼓拍（2、4 拍）100° 斜条纹 difference 闪。HUD：标题 + 段名、BAR/BEAT 计数、四格拍点、底部频谱条（底鼓/镲片确定性包络）。内置 WebAudio 合成鼓点并用 120ms 前瞻调度对齐画面。减少动态关闭闪光与震动。","videoPrompt":"Kinetic typography lyric video, 1920×1080, 30 seconds at 96 BPM, every change locked to the beat. Flat solid color fields cycling between charcoal, signal red, electric blue and off-white, each new section wiping in from the left. Huge condensed uppercase words slam onto the screen exactly on each beat — no fades, just a quick settle from 150% to 100% — and bob slightly on the offbeat. Bold Chinese characters rise from behind an invisible baseline mask. A 2×4 outlined grid fills one word per beat, then cells invert in a checker rhythm. A build-up stacks the word \"UP\" on eighth notes, growing and rotating with fading echoes while diagonal stripes flash faster and faster. The drop: a giant word fills the frame, background and text colors swap every beat with a camera punch on each kick. Minimal HUD with bar/beat counter and four beat squares, a small spectrum at the bottom. Tight, musical, graphic.","negativePrompt":"不要淡入淡出；不要让词的出现时间偏离拍点；不要所有层同时用同一频率运动；不要渐变和照片背景；不要超过四种主色。","migration":[{"field":"config.js → bpm / bars","how":"速度与小节数；时长自动计算。"},{"field":"config.js → lyrics","how":"拍号表：beat（可为 .5）、text、style（count/slam/rise/stack/build/giant）、hold；stack 用 cell 指定格子。"},{"field":"config.js → sections","how":"每段起始小节、底色/字色/强调色；strobe 数组用于 Drop 每拍换色。"},{"field":"config.js → pattern","how":"十六步鼓点字符串（x 触发）、低音、Build/Drop 起止拍。"},{"field":"接真实歌曲","how":"用 <audio> 播放并以 audio.currentTime 作为 t；按歌曲 BPM 与第一拍偏移（offset）重写 lyrics。"}],"demo":"demos/cases/beat-lyric/index.html","research":"docs/research/beat-lyric.md","patternIds":["beat-clock","word-slam","seekable-timeline"],"sources":[{"title":"原创设计语言 · Motion Atlas","type":"原创","note":"动态字体 / 歌词视频的通用语法（拍入、遮罩、卡点）整理为可配置的拍号系统；歌词与鼓点原创。"}],"preview":"previews/cases/beat-lyric.jpg","previewPortrait":null},{"id":"mission-fui","order":7,"title":"任务指挥台 · 荧光 FUI","subtitle":"MISSION CONTROL / RADAR · LOCK · ALERT STATE","carriers":["console","video"],"source":"original","evidence":"original","capturedAt":"2026-10-14","tags":["FUI","雷达余辉","阶梯锁定","告警态","示波器","等宽"],"summary":"黑底荧光青的指挥台：雷达扫描带余辉、目标被扫到时点亮再衰减；锁定括号分四档“咔咔”收紧；遥测波形、系统条与逐行日志持续刷新；整台设备在 NOMINAL / CAUTION / ALERT 三种状态间一起换色、换闪烁节奏。","focus":"影视 FUI（Fantasy UI）的魅力来自“系统在持续工作”与“状态一变全体响应”。这个原创语言把两件事做成了机制：持续层（扫描、波形、日志）用不同周期叠加出生命感；状态层只有一个变量（告警态），所有组件读同一组颜色与闪烁参数，一次切换整台设备变色。","accent":"#5ff3ff","background":"#05080b","timeline":true,"kit":true,"previewAt":14,"energy":[0.3,0.35,0.35,0.4,0.4,0.6,0.65,0.55,0.6,0.7,0.75,0.9,1,0.95,0.9,0.6,0.4,0.35],"rhythm":{"duration":20,"beats":[{"t":0.1,"label":"面板展开","note":"三块面板以 snap 缓动从左向右裁切展开，顶部状态栏淡入。"},{"t":1.6,"label":"持续层","note":"雷达 4 秒一圈、波形每帧刷新、日志逐行打字——三种周期叠加。"},{"t":6,"label":"锁定","note":"括号从 240px 分四档收紧到 48px（每档 snap 80ms、间隔 150ms），同时从 45° 旋正；1.6 秒后显示 LOCK。"},{"t":9.5,"label":"CAUTION","note":"400ms 内全体颜色插值到琥珀色，状态标签 1Hz 闪烁，边缘静态辉光，波形幅度增大。"},{"t":12.5,"label":"ALERT","note":"全体换红，标签 2Hz 闪烁，边缘辉光脉冲，波形出现锯齿，护盾条剧烈波动，警报音交替。"},{"t":16.6,"label":"恢复","note":"颜色回到荧光青，日志写入“威胁解除”。"}]},"layers":[{"name":"框架","role":"黑底、细描边面板 + 对角角标、顶栏状态、底部命令行与扫描线纹理。"},{"name":"持续层","role":"雷达扫描与余辉、遥测双轨波形、系统条、逐行日志、UTC 时钟。"},{"name":"交互层","role":"目标列表、锁定括号与标签、目标数据打字。"},{"name":"状态层","role":"一个告警态变量驱动：全部颜色、闪烁频率、边缘辉光、数据波动幅度。"}],"composition":{"color":"荧光青 #5ff3ff 单色系统（主色 + 暗色 + 底色 + 面板色 4 个变量）；告警态整体替换为琥珀 #ffb000 或红 #ff3b30，不出现第二种强调色。","typography":"全等宽字体：编号与数值对齐、字距放宽到 .14–.3em；只有锁定目标编号用大字号。","layout":"左（列表/锁定）—中（雷达）—右（遥测/日志）三栏，中心是最大的圆形扫描区；所有面板带两个对角的角标。","imagery":"无图片：雷达同心圆、方位刻度、速度矢量、示波器网格与波形就是全部图像。","motion":"持续运动用匀速/正弦（扫描、波形），离散事件用 snap 阶梯（锁定）与打字（日志/命令），状态切换用 400ms 颜色插值 + 固定频率闪烁。","sound":"每圈扫描一声下滑音、锁定三声上行短音、CAUTION 提示音、ALERT 交替警报、恢复和弦（默认关闭）。","rhythm":"扫描 4 秒/圈为基础节拍；锁定事件约 1.6 秒；状态每 3–4 秒升级一次，形成“平静—紧张—爆发—回落”。","coherence":"组件不自己判断状态，只读 CSS 变量与同一个闪烁时钟，所以切换永远整齐。"},"tokens":{"palette":["#05080b","#0a1117","#1d4a55","#5ff3ff","#ffb000","#ff3b30"],"type":"JetBrains Mono / Cascadia Mono 全等宽","motion":[{"name":"sweep","value":"周期 4s；余辉 0.9rad 锥形渐变（α .18）；目标亮度 e^(−1.3Δt)"},{"name":"lock","value":"240→180→120→80→48px，每档 snap 80ms、间隔 150ms，45°→0°；确认 1.6s"},{"name":"state","value":"颜色 400ms inOutCubic；闪烁 0 / 1Hz / 2Hz；ALERT 边缘辉光 2Hz 脉冲"},{"name":"log","value":"每行 600ms 打字；最新行高亮 1.5s"},{"name":"boot","value":"面板裁切展开 1.2s snap"}]},"interaction":["点击左侧目标进行锁定；按 1 / 2 / 3 切换 NOMINAL / CAUTION / ALERT。","自动演示由时间轴驱动，真实输入切换为实时；站内刻度条或重播回到自动演示。","声音默认关闭；减少动态时关闭闪烁与辉光脉冲，不自动播放。","Canvas 内刻度文字按画布缩放换算，保证 ≥12px。"],"useCases":["科幻影视 FUI","安防/监控大屏","游戏 HUD 与雷达","发布会“系统演示”","直播数据监控"],"avoid":["日常办公后台","需要长时间阅读的内容","光敏人群（ALERT 闪烁）"],"constraints":["原创设计语言：任务、目标与数据均为虚构。","ALERT 闪烁为 2Hz，低于常见光敏阈值；正式产品仍应提供关闭选项。"],"prompt":"做一个荧光 FUI 任务指挥台（HTML/CSS/JS + Canvas，可 seek）：黑底 #05080b，荧光青 #5ff3ff 单色系统，全等宽字体。三栏布局：左侧目标列表（编号/类型/距离）与锁定信息框；中间正方形雷达 Canvas（4 道同心圆、十字线、每 10° 刻度、每 30° 三位数方位、扫描线 4 秒一圈、身后 0.9rad 锥形渐变余辉、目标亮度 = e^(−1.3×扫描离开后的秒数)、被扫到时外扩环、未知目标用菱形、速度矢量）；右侧双轨遥测示波器、4 条系统条、逐行打字的事件日志；顶栏任务名、告警态标签、UTC 时钟；底部命令行。面板细描边 + 两个对角角标，全屏淡扫描线纹理。锁定：括号从 240px 按 240→180→120→80→48 分四档阶梯收紧（每档 snap 80ms、间隔 150ms）并从 45° 旋正，1.6 秒后标签由 ACQ ■■□□ 变为 LOCK，数据逐项打字。告警态：一个变量驱动全部 CSS 颜色（400ms 插值）、状态标签闪烁（0/1/2Hz）、边缘内发光（ALERT 2Hz 脉冲）、波形幅度与锯齿、系统条波动。点击目标锁定，1/2/3 切换状态；声音默认关闭；减少动态关闭闪烁；Canvas 文字按缩放保证 ≥12px。","videoPrompt":"Sci-fi mission control FUI, 1920×1080, 20 seconds, monospace typography, near-black background with a single phosphor cyan color. Three-panel layout: a contact list on the left, a large circular radar in the center with concentric rings, bearing ticks and a sweeping line trailing a soft cone of afterglow — blips flare when the sweep passes and fade like phosphor; telemetry oscilloscope traces, status bars and a typing event log on the right. Thin outlined panels with corner brackets, faint scanlines. A target gets locked: square brackets snap tighter in four mechanical steps while rotating upright, then a \"LOCK\" tag appears. The whole interface shifts to amber CAUTION with a 1Hz blinking status, then to red ALERT with a 2Hz pulse, jagged waveforms and a glowing pulsing screen edge, before calming back to cyan. Precise, cinematic, no clutter.","negativePrompt":"不要多色霓虹混用；不要无意义的随机数字雨；不要让组件各自独立判断状态；不要平滑缩放的锁定框；不要高频（>3Hz）闪烁。","migration":[{"field":"config.js → states","how":"每个告警态的主色/暗色/底色/面板色与闪烁频率；可增加新状态。"},{"field":"config.js → contacts","how":"目标的极坐标（半径比例、方位角）、径向/角速度与类型。"},{"field":"config.js → radar","how":"扫描周期、环数、量程、余辉衰减。"},{"field":"config.js → log / autopilot","how":"日志文本与时刻；自动演示的锁定与状态切换。"},{"field":"style.css","how":"面板角标、扫描线纹理、字体与栏宽。"}],"demo":"demos/cases/mission-fui/index.html","research":"docs/research/mission-fui.md","patternIds":["radar-sweep","target-lock","alert-state","text-scramble"],"sources":[{"title":"原创设计语言 · Motion Atlas","type":"原创","note":"参考影视 FUI 的通用元素（雷达、锁定、示波器、告警态）设计；所有数据虚构。"}],"preview":"previews/cases/mission-fui.jpg","previewPortrait":null},{"id":"gacha-reveal","order":8,"title":"抽卡揭示舞台 · 期待与释放","subtitle":"STELLAR DRAW / CHARGE · TELL · BURST · FLIP","carriers":["showcase","video"],"source":"original","evidence":"original","capturedAt":"2026-10-14","tags":["期待感","稀有度预示","升格假动作","冲击波","翻牌流光","光柱"],"summary":"把“揭示”拆成可调的节拍：粒子螺旋内收蓄力 → 光球给出预示色 → 金色先给紫色再升格 → 闪白冲击波爆发 → 十张卡从中心飞入 → 逐张翻面并扫过流光 → 金卡多停一拍、光柱升起再翻开。","focus":"揭示类交互（抽奖、开箱、成绩公布、新品发布）的情绪曲线几乎一样：等待越长、信息越分步给出，释放越爽。这个原创语言把“期待—预示—假动作—释放—逐个确认—高潮停顿”写成时间参数，任何揭示场景都能套用。","accent":"#ffcf4a","background":"#07061a","timeline":true,"kit":true,"previewAt":6.3,"energy":[0.15,0.3,0.45,0.6,0.75,0.9,1,0.7,0.6,0.6,0.65,0.7,0.85,0.95,0.6,0.4],"rhythm":{"duration":9.5,"beats":[{"t":0.6,"label":"按下 · 蓄力","note":"粒子从散布状态螺旋内收，越接近爆发转得越快；光球随蓄力放大；低频上滑音。"},{"t":2.1,"label":"预示色","note":"光球与粒子染上“当前最高稀有度”的颜色（金卡先给紫色），弱闪白。"},{"t":2.55,"label":"升格","note":"仅最高稀有度：颜色从紫变金，光球抖动并再放大一级，中等闪白。"},{"t":2.9,"label":"爆发","note":"强闪白、椭圆冲击波、粒子径向飞散淡出。"},{"t":3.2,"label":"飞入","note":"十张卡背面朝上从中心旋转放大飞到 5×2 网格，错峰 70ms，背面描边为各自稀有度色。"},{"t":4.1,"label":"逐张翻牌","note":"按位置依次 rotateY 180°（outBack，略超再回正），错峰 120ms，翻开后流光扫过。"},{"t":5.9,"label":"金卡","note":"最后翻、额外停 0.7s；翻开前光柱升起，翻开后外发光与轻微放大脉冲，五和弦。"},{"t":7,"label":"结果","note":"统计行与“再来一次”按钮回弹出现。"}]},"layers":[{"name":"星空","role":"深靛蓝径向渐变 + 两层星点。"},{"name":"粒子","role":"Canvas：160 个固定种子粒子，按时间计算螺旋/爆发位置。"},{"name":"光球","role":"双环（实线 + 虚线反向旋转）+ 发光核心，颜色读取预示色变量。"},{"name":"卡牌","role":"3D 翻转卡（背面斜纹 + 稀有度描边；正面渐变 + 图形 + 名字 + 星级 + 流光）。"},{"name":"闪光与光柱","role":"全屏闪白（三档强度）与金卡光柱。"}],"composition":{"color":"深靛蓝夜空为底；稀有度三色：蓝 #4aa8ff / 紫 #b06bff / 金 #ffcf4a——同一种颜色既是预示也是卡牌描边，形成“前后呼应”。","typography":"标题用宽字距衬线（仪式感），卡名用粗无衬线大写，统计用等宽小字。","layout":"中心对称：所有能量汇聚到画面中心，再向 5×2 网格发散；按钮在底部中轴。","imagery":"原创几何图形卡面（月、焰、星、波、羽、日、叶、冠），用色块渐变区分稀有度。","motion":"蓄力用加速（inCubic），释放用 outExpo，翻牌用 outBack；整体是“慢—更慢—瞬间—逐个—停顿—高潮”。","sound":"蓄力上滑、预示单音、升格碎裂 + 高音、爆发低频冲击、普通卡短音、金卡五和弦（默认关闭）。","rhythm":"蓄力 1.5s，预示到爆发 0.8s（含 0.45s 假动作），飞入 0.9s，翻牌每张 120ms，金卡前停 0.7s。","coherence":"稀有度色贯穿粒子、光球、卡背描边、卡面渐变和光柱，用户能把每个阶段的信息串成一个故事。"},"tokens":{"palette":["#07061a","#2a1f6b","#4aa8ff","#b06bff","#ffcf4a","#ffffff"],"type":"Georgia 宽字距标题 + Bahnschrift 粗体卡名","motion":[{"name":"charge","value":"1.5–2.3s inCubic；粒子角速度随进度 ×4，半径 ×0.1"},{"name":"tell","value":"弱闪白 0.35·e^(−10t)"},{"name":"upgrade","value":"中闪白 0.7·e^(−9t) + 光球抖动 ±4px、放大 0.25"},{"name":"burst","value":"强闪白 e^(−5t)；冲击波 0.8s；粒子 outExpo 1.2s"},{"name":"fly","value":"500ms outCubic，错峰 70ms，旋转 −25°→0，缩放 0.2→1"},{"name":"flip","value":"450ms outBack rotateY 0→180°（最大 194°）；流光 600ms，延迟 300ms"},{"name":"gold-pause","value":"额外 0.7s；光柱提前 0.45s 升起"}]},"interaction":["“DRAW ×10”开始（定位到按下时刻并播放），“跳过”直接到结果。","空格播放/暂停；刻度条标出每个阶段。","声音默认关闭；减少动态时关闭闪白，直接显示结果。"],"useCases":["游戏抽卡/开箱","抽奖与开奖直播","成绩/名次公布","新品发布揭幕","活动奖励领取"],"avoid":["与金钱相关的诱导性设计（需遵守当地法规与概率公示）","光敏人群（闪白）"],"constraints":["原创设计语言：卡牌名称与图形原创，无任何游戏素材。","Demo 结果固定写在 config.js，不涉及真实概率；正式产品需按法规公示概率。"],"prompt":"做一个“十连抽卡”揭示舞台（HTML/CSS/JS + Canvas，可 seek）：深靛蓝星空背景；稀有度三色 蓝 #4aa8ff / 紫 #b06bff / 金 #ffcf4a。节拍：①按下（0.6s）后 160 个固定种子粒子螺旋内收，角速度随进度加速、半径收缩到 10%，中心光球（双环反向旋转 + 发光核心）随蓄力放大，低频上滑音；②2.1s 预示色：粒子与光球染成最高稀有度色（若为金，先给紫色），弱闪白；③2.55s 升格（仅金）：紫变金、光球抖动并再放大、中闪白；④2.9s 爆发：强闪白、椭圆冲击波、粒子 outExpo 径向飞散；⑤3.2s 十张卡背面朝上从中心旋转放大飞入 5×2 网格（500ms，错峰 70ms，卡背描边为稀有度色）；⑥4.1s 起按位置逐张 rotateY 翻面（450ms outBack，错峰 120ms），翻开后一道斜向流光扫过；⑦金卡最后翻、额外停 0.7s，翻面前竖直光柱升起，翻开后外发光与放大脉冲；⑧7s 显示统计与“再来一次”。提供跳过按钮；结果写在配置中；声音默认关闭；减少动态关闭闪白。","videoPrompt":"Mobile-game style ten-pull summon reveal, 1920×1080, 9 seconds. Deep indigo starry sky. Glowing particles spiral inward faster and faster toward a pulsing orb with two counter-rotating rings. The orb turns purple — a fake-out — then cracks, shakes and upgrades to gold with a bright flash. A white burst and an elliptical shockwave blow the particles outward. Ten face-down cards with glowing rarity-colored edges spin out from the center into a 5×2 grid, then flip one by one with a slight overshoot and a diagonal light sheen sweeping across each face (blue, purple cards with simple white glyphs). The last card waits an extra beat as a golden light pillar rises, then flips to reveal a gold crown card with a pulsing glow. Satisfying anticipation-and-release rhythm.","negativePrompt":"不要一次性同时翻开所有卡；不要省略预示与停顿（会失去期待感）；不要使用真实游戏角色与美术；不要用随机结果制造虚假概率暗示。","migration":[{"field":"config.js → results","how":"十张卡的稀有度、名称、图形；最高稀有度自动决定预示色与是否升格。"},{"field":"config.js → rarityColors","how":"各稀有度的颜色（贯穿粒子、光球、描边、光柱）。"},{"field":"config.js → timing","how":"蓄力、预示、升格、爆发、飞入、翻牌、金卡停顿、结果的时刻。"},{"field":"script.js → GLYPH / GRAD","how":"卡面图形与渐变；可替换为真实卡面图片。"}],"demo":"demos/cases/gacha-reveal/index.html","research":"docs/research/gacha-reveal.md","patternIds":["charge-release","card-flip-sheen"],"sources":[{"title":"原创设计语言 · Motion Atlas","type":"原创","note":"揭示类交互（抽卡、开箱、开奖）的通用情绪曲线；卡牌与图形原创。"}],"preview":"previews/cases/gacha-reveal.jpg","previewPortrait":null},{"id":"ink-scroll","order":9,"title":"水墨长卷展台 · 手卷式浏览","subtitle":"INK HANDSCROLL / UNROLL · BLEED · PARALLAX · SEAL","carriers":["showcase","video"],"source":"original","evidence":"original","capturedAt":"2026-10-14","tags":["手卷","自右向左","墨晕显影","多层视差","竖排题诗","印章"],"summary":"一卷可以“展开”的山水手卷：自右向左展开，远中近三层墨色依次晕开，竖排题诗笔刷式显现，镜头沿阅读方向平移并带出层层视差，最后在卷尾落下一方朱印；之后可以拖动、滚轮或用缩略图自由浏览。","focus":"中国手卷的观看方式本身就是一种“时间轴”：一段段展开、从右往左读、边看边走。这个原创语言把它变成展示台的交互模型——展开是开场、墨晕是揭示、平移是叙事、盖章是结尾——适合博物馆、文旅、品牌长图与产品时间线。","accent":"#b8322a","background":"#f1ead8","timeline":true,"kit":true,"previewAt":7.5,"energy":[0.1,0.3,0.45,0.55,0.6,0.55,0.5,0.45,0.45,0.5,0.5,0.5,0.8,0.4,0.3],"rhythm":{"duration":14.5,"beats":[{"t":0.5,"label":"展开","note":"右轴固定，左轴 2.1s（outCubic）向左滑开，纸面在两轴之间显露。"},{"t":2.2,"label":"远山晕开","note":"扩散遮罩从画面右中部外推，湍流位移 70→0、模糊 6→0，像墨在宣纸上洇开。"},{"t":3,"label":"中景","note":"中景山与小舟、飞鸟晕开；雾带淡入。"},{"t":3.8,"label":"近景","note":"近山与松树晕开，墨色最重。"},{"t":5,"label":"题诗","note":"竖排“行到水穷处 / 坐看云起时”逐列自上而下显现，落款与小印随后。"},{"t":6.4,"label":"平移","note":"镜头沿阅读方向自右向左平移 5.2s（inOutCubic），三层山与两条雾带以不同视差移动。"},{"t":12,"label":"盖章","note":"卷尾朱印 1.35→1 回弹落下，红色扩散环与纸面微震，低频“咚”。"}]},"layers":[{"name":"展室","role":"暗色木调背景，聚光感径向渐变。"},{"name":"纸面","role":"米色宣纸 + 分形噪声纹理，两端木轴。"},{"name":"墨层","role":"远（视差 .35）/ 中（.6）/ 近（1.0）三层程序化山水，每层墨色深浅不同。"},{"name":"雾带","role":"两条横向雾带，视差 .8 与 1.1，并缓慢自漂。"},{"name":"文字与印","role":"竖排楷体题诗、落款、小印；卷尾大印。"},{"name":"导航","role":"底部缩略图与视窗框（可点击跳转）。"}],"composition":{"color":"墨的五色（焦、浓、重、淡、清）用同一墨色的不同透明度表达；唯一彩色是朱印 #b8322a。","typography":"楷体竖排，宽字距；落款小字；不使用无衬线。","layout":"手卷横幅，远山高、近山低，留白（雾与天）占画面近半；题诗位于卷首右上，印章位于卷尾。","imagery":"程序化山脊（值噪声）+ 墨色渐变 + 沿山脊的皴笔线 + 松树笔触；小舟与飞鸟点景。","motion":"慢：展开 2.1s、晕开 1.6s/层、平移 5.2s；唯一的“快”是盖章的回弹与微震。","sound":"展开时纸张摩擦噪声、每层晕开一个低沉长音、盖章一声“咚”（默认关闭）。","rhythm":"按“展开—显影—题字—行走—落款”的书画节奏，事件间隔 0.8–1.2s，平移段给足呼吸。","coherence":"所有动效都对应真实的书画行为（展卷、落墨、题字、移步、钤印），东方审美来自“动作的合理性”，而不只是配色。"},"tokens":{"palette":["#f1ead8","#1e1d1b","#b8322a","#f6f1e3","#8a5a32"],"type":"楷体（KaiTi / STKaiti / Kaiti SC）竖排","motion":[{"name":"unroll","value":"2.1s outCubic，自右向左"},{"name":"bleed","value":"每层 1.6s outCubic：遮罩外推 + 湍流位移 70→0 + 模糊 6→0；层间 0.8s"},{"name":"brush-text","value":"每列 1.1s，遮罩自上而下，轻微模糊 1.2→0"},{"name":"pan","value":"5.2s inOutCubic；视差 .35 / .6 / 1.0；雾 .8 / 1.1"},{"name":"stamp","value":"260ms outBack 1.35→1、−6°→−2°；扩散环 0.8s；微震 6px·e^(−14t)"},{"name":"browse","value":"用户浏览用临界阻尼跟随（速率 7）"}]},"interaction":["动画结束后：拖动画卷、滚轮、←/→ 或点击缩略图浏览；镜头以临界阻尼跟随。","空格播放/暂停；站内刻度条或重播回到自动演示。","声音默认关闭；减少动态时关闭墨晕扰动与微震，直接显示完整画面。"],"useCases":["博物馆/书画数字展","文旅长卷导览","品牌长图与年度时间线","产品发展历程","东方美学发布会"],"avoid":["需要快速检索信息的场景","竖屏短视频（横幅比例不适合）"],"constraints":["原创设计语言：山水为程序化生成；王维《终南别业》为公有领域。","超宽元素的 SVG 滤镜会被浏览器截断，Demo 只在晕开期间启用滤镜并把区域限制在可见窗口。"],"prompt":"做一个水墨长卷展台（HTML/CSS/JS + SVG，可 seek）：暗色展室中一幅宽为视口 3.2 倍的米色宣纸手卷（分形噪声纹理），两端木轴。①展开：右轴固定，左轴 2.1s outCubic 向左滑开，纸面用 clip-path 在两轴之间显露；②墨层：远/中/近三层程序化山水（值噪声山脊 + 同一墨色不同透明度的竖向渐变 + 沿山脊的皴笔描边；近层加松树、中层加小舟与飞鸟），视差系数 .35/.6/1.0；每层依次（间隔 0.8s）晕开：径向遮罩从画面中右部外推 + feTurbulence/feDisplacementMap 位移 70→0 + 模糊 6→0（滤镜只在晕开时启用，区域限定为可见窗口）；两条雾带视差 .8/1.1 并缓慢自漂；③题诗：竖排楷体两列自上而下遮罩显现（每列 1.1s），落款与小朱印随后；④平移：镜头自右向左 5.2s inOutCubic；⑤盖章：卷尾朱印 260ms outBack 从 1.35 落到 1、−6°→−2°，红色扩散环与纸面微震；⑥之后可拖动/滚轮/方向键/点击缩略图浏览，镜头临界阻尼跟随。声音默认关闭；减少动态关闭扰动与震动。","videoPrompt":"A traditional Chinese ink landscape handscroll unrolling in a dim gallery, 1920×1080, 14 seconds. Cream rice paper with subtle texture between two wooden rollers; the left roller glides left to reveal the painting from right to left. Mountain layers appear one by one as if ink were bleeding into wet paper — far pale peaks, mid-ground ridges with a tiny boat and flying birds, then dark near hills with pine trees — with soft horizontal mist bands. A vertical poem in brush calligraphy reveals from top to bottom with a small red seal. The camera slowly pans right-to-left along the scroll with gentle parallax between the layers. At the end a red square seal stamp presses down with a small bounce and a faint red ripple. Calm, elegant, contemplative; monochrome ink with one red accent.","negativePrompt":"不要彩色山水与渐变天空；不要从左往右展开或平移；不要无衬线字体；不要快速闪烁与弹跳（盖章除外）；不要使用受版权保护的名画。","migration":[{"field":"config.js → span / layers","how":"长卷宽度倍数；每层的视差、墨色浓度、山高、峰数、晕开时刻与随机种子。"},{"field":"config.js → poem / seal","how":"竖排题诗（建议使用公有领域或自有文本）、落款、印章文字。"},{"field":"config.js → timing","how":"展开、题诗、平移起止与盖章时刻。"},{"field":"config.js → palette","how":"纸色、墨色、印泥色、雾色。"},{"field":"换成真实画作","how":"把各层 SVG 换成分层切好的透明 PNG/WebP（远中近），保持视差与晕开机制。"}],"demo":"demos/cases/ink-scroll/index.html","research":"docs/research/ink-scroll.md","patternIds":["ink-bleed","seal-stamp"],"sources":[{"title":"原创设计语言 · Motion Atlas","type":"原创","note":"手卷观看方式（自右向左展开、移步换景）转译为展示台交互；山水程序化生成。"},{"title":"王维《终南别业》","type":"资料 · 公有领域","note":"题诗“行到水穷处，坐看云起时”。"}],"preview":"previews/cases/ink-scroll.jpg","previewPortrait":null}],"patterns":[{"id":"corner-hud","order":10,"title":"四角信息 HUD","types":["hud","composition"],"carriers":["video","console","showcase"],"summary":"把日序、坐标、时间、音乐与进度固定在四个角，中央留给世界；信息持续更新，画面就有了“系统在运行”的感觉。","mechanism":"左上日序与日期、右上坐标/海拔/缩放与大号时钟、左下正在播放与双语歌词、右下旅程步进器；顶部一条贯穿细线按进度填充强调色。数值由时间轨道驱动：时钟在同一天内连续推进、跨天时跳变；日序变化时数字从下方滚入。","trigger":"时间推进 / 旅程进度变化","effect":"信息层稳定而持续变化，观众随时知道“现在是哪天、几点、在哪、走到哪”。","timing":[{"name":"日序滚入","value":"460ms outCubic"},{"name":"歌词打字","value":"700ms 线性，副行延迟 400ms 淡入"},{"name":"进度细线","value":"与步进器共用同一进度值，inOutCubic"},{"name":"字号","value":"标签 12px 等宽、时钟 26–44px、日序 16–24px"}],"useCases":["旅行与巡礼影像","直播/转播的持续信息层","操作台状态栏","展示台导览"],"avoid":["信息本身不随时间变化的静态海报","需要大面积正文阅读的页面"],"accessibility":{"reducedMotion":"数值直接更新、不做滚入；时间轴静止在信息完整的一帧。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"foundation","pairsWellWith":["route-draw-marker","chapter-frame","collect-counter","vertical-title-blur"],"conflicts":[],"notes":"四角各管一类信息，不要在同一角堆叠第二套系统；全屏图片时 HUD 改白字并加上下压暗层。"},"prompt":"为【影像/操作台】加一套四角 HUD：左上“DAY 01 / 03”（日序数字用强调色，变化时 460ms 从下方滚入）+ 12px 等宽日期；右上 12px 等宽纬经度与“ELEV · Z”缩放，旁边 26–44px 等宽大号时钟 + 时区角标；左下 NOW PLAYING（均衡器小图标）+ 曲名 — 艺人 + 一行加粗歌词与一行灰色译文（打字推进）；右下 4 站旅程步进器（节点实心表示已到达，连线按进度填充）；顶部贯穿一条 1px 细线，按旅程进度填充 3px 强调色。所有数值由时间轨道驱动、可 seek；中央完全留空给画面。所有文字 ≥12px。","demo":"demos/patterns/corner-hud/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"全片持续显示 DAY xx / 07、日期、坐标、ELEV·Z、JST 时钟、YUI SPOTTED 计数、NOW PLAYING 与双语歌词、SEOUL–KANSAI–KYOTO–TOKYO 步进器。","evidence":"observed","locator":"0:16.5、1:14.5、2:08.5"}],"previewAt":7.2,"preview":"previews/patterns/corner-hud.jpg","previewPortrait":null},{"id":"vertical-title-blur","order":11,"title":"竖排汉字模糊入场 + 英文打字","types":["type-motion"],"carriers":["video","showcase","console"],"summary":"粗黑竖排汉字自上而下逐字由模糊变清晰，横线描出，英文标题带模糊前沿打出：一组同时有“东方字形”和“系统输出”气质的标题。","mechanism":"汉字逐字错峰 140ms，每字 500ms：透明 0→1、模糊 14px→0、上移 10px→0。横线从左向右 scaleX 描出。英文按字符推进，前沿 2 个字符带 6px 模糊，像正在“对焦”。字幕模式改为白色衬线、更慢的错峰（300ms），配合斜体英文。","trigger":"章节开始 / 抵达地点 / 回忆字幕","effect":"标题出现有方向和速度感，阅读顺序被动画引导：先汉字、再英文、最后小字。","timing":[{"name":"字间错峰","value":"140–160ms（字幕 300ms）"},{"name":"单字时长","value":"500ms outCubic"},{"name":"初始模糊","value":"14px（字幕 10px）"},{"name":"英文打字","value":"约 45ms/字符，前沿 2 字符模糊"},{"name":"离场","value":"450ms 整体模糊 10px + 透明"}],"useCases":["片名与章节标题","地名卡","回忆字幕","展示台展品名"],"avoid":["长段落","需要即时读取的操作提示"],"accessibility":{"reducedMotion":"直接显示完整标题，不做模糊与逐字。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"accent","pairsWellWith":["corner-hud","chapter-frame","card-expand-fullscreen"],"conflicts":[],"notes":"同屏只保留一组模糊入场标题；与卡片同时出现时放在对角（标题左上、卡片右侧）。"},"prompt":"实现“竖排汉字模糊入场 + 英文打字”标题：汉字 writing-mode: vertical-rl，900 字重，每字独立 span；第 i 个字在 start + i×140ms 开始，500ms outCubic 内 opacity 0→1、filter blur(14px)→0、translateY(-10px)→0。汉字右侧一条 3px 横线 450ms scaleX 0→1，下方英文标题按字符打出（约 45ms/字符），正在出现的前两个字符带 6px 模糊。离场时整组 450ms 模糊到 10px 并淡出。提供字幕变体：白色衬线、字间 300ms、斜体英文副句。全部动画是时间 t 的纯函数。","demo":"demos/patterns/vertical-title-blur/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"「聖地巡礼」「関西」「西宮北口」「京都」等竖排地名逐字模糊入场，英文地名从左向右打出且前沿模糊；回忆段竖排日文字幕逐字揭示。","evidence":"observed","locator":"0:06.4、0:16.5、0:21.5、0:55.5"}],"previewAt":2.6,"preview":"previews/patterns/vertical-title-blur.jpg","previewPortrait":null},{"id":"route-draw-marker","order":12,"title":"路线描画与标记脉冲","types":["camera","hud"],"carriers":["video","showcase"],"summary":"虚线航线带弧度飞越、地面路线白色描边加强调色，头部圆点领路；地图标记出现时回弹、标签打字、双环脉冲持续呼吸。","mechanism":"路线按弧长截断到进度 p（inOutQuad），头部圆点停在截断点；航线用二次贝塞尔弧并加虚线，地面路线用白色粗描边垫底。标记 450ms outBack 回弹出现，标签打字 550ms，汉字延迟淡入；两个脉冲环相位差半个周期，2 秒一圈放大 2.6 倍并淡出。","trigger":"行程段开始 / 抵达","effect":"移动被“画”出来，空间关系和先后顺序一眼可读。","timing":[{"name":"描画","value":"按段时长 inOutQuad；航线约 3s、地面 2.5–3.5s"},{"name":"标记回弹","value":"450ms outBack，缩放 0.6→1"},{"name":"脉冲","value":"周期 2s，两环相位差 0.5，最大 2.6×"},{"name":"标签","value":"打字 550ms，汉字 +600ms 淡入"}],"useCases":["旅行/物流路线","赛事路线","展示台导览地图"],"avoid":["没有空间意义的流程图"],"accessibility":{"reducedMotion":"路线一次画完，脉冲停止为静态双环。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["corner-hud","alert-reroute","card-expand-fullscreen"],"conflicts":[],"notes":"在真实地图中把路线放进 GL 图层（大俯仰角下 project 会把相机后方的点投影错位）；标记可以留在 DOM。"},"prompt":"在【地图/示意图】上实现路线描画：路线点集按累计弧长截断到进度 p（inOutQuad），航线用二次贝塞尔弧（控制点沿垂线偏移 bend×距离）+ 9/7 虚线，地面路线先画 9px 白色描边再画 4px 强调色；描画期间在截断点显示白底黑边头部圆点。标记：16px 白底黑边圆点内嵌强调色，450ms outBack 从 0.6 缩放回弹出现；右侧等宽标签 550ms 打字，汉字随后淡入；两个 1.5px 脉冲环每 2 秒放大到 2.6 倍并淡出，相位相差半周期。接真实地图时把路线放进 MapLibre GeoJSON line 图层。","demo":"demos/patterns/route-draw-marker/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"首尔→关西虚线航线、地铁/铁路实线随行程描出，标记带脉冲环与英中标签，路线颜色随作品主题变化。","evidence":"observed","locator":"0:10.5、0:16.5、1:44.5"}],"previewAt":8.6,"preview":"previews/patterns/route-draw-marker.jpg","previewPortrait":null},{"id":"day-night-flip","order":13,"title":"昼夜翻转：逐层插值","types":["transition","composition"],"carriers":["video","console","showcase"],"summary":"用约 1 秒把世界从白天换到夜晚：按图层类别逐个插值颜色，中途经过灰阶。对照整体反色可以看到差别——反色会让水比陆地更亮。","mechanism":"为背景、水、绿地、建筑、道路、描边、路线、文字各定一组 [白天, 夜晚] 颜色，以同一个 night 值（0–1，inOutCubic）插值；HUD 文字与纸色同步。真实地图里遍历样式图层分类后 setPaintProperty，并缓存避免重复设置。","trigger":"时间流逝 / 跨天 / 章节气氛切换","effect":"时间感和情绪变化，而不必切镜头。","timing":[{"name":"时长","value":"0.9–1.2s inOutCubic"},{"name":"中点","value":"画面经过灰阶，像“天色渐变”"},{"name":"配色","value":"陆地 #eeebe4→#1b2431，水 #bccdd9→#0d131c，道路 #fff→#2c3648"}],"useCases":["旅行影像跨天","指挥台日夜模式","展示台主题切换"],"avoid":["频繁来回切换造成闪烁"],"accessibility":{"reducedMotion":"直接切换到目标配色，不做中间过渡。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["corner-hud","route-draw-marker"],"conflicts":[],"notes":"路线和标记的颜色要单独定义夜晚值，不要跟着底图一起反色。"},"prompt":"实现昼夜翻转：为每类图层定义 [白天, 夜晚] 两个颜色（背景/陆地、水、绿地、建筑、道路、道路描边、路线、文字），用 night∈[0,1] 统一插值，0.9–1.2s inOutCubic，过渡中途画面经过灰阶。若是 MapLibre，加载后遍历 style.layers 按 id 关键词归类（water/park/building/highway/casing/railway/boundary），每帧仅在值变化时 setPaintProperty。HUD 的纸色与墨色同步插值。不要用 CSS invert 做整张夜景（会让水比陆地亮）。","demo":"demos/patterns/day-night-flip/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"片头深色地球 → 灰 → 亮约 0.9 秒；之后多次随时间进入夜间暗色地图，次日早晨再变亮。","evidence":"observed","locator":"0:05.2–0:06.1、0:38.6–0:39.2"}],"previewAt":4,"preview":"previews/patterns/day-night-flip.jpg","previewPortrait":null},{"id":"card-expand-fullscreen","order":14,"title":"卡片展开为全屏","types":["transition"],"carriers":["video","showcase"],"summary":"地图上的照片卡片 600ms 平滑展开为全屏实景，HUD 保留并转白、上下压暗，停留时缓慢推近，再收回卡片——高光片段不脱离“系统”。","mechanism":"记录卡片静止矩形与全屏矩形，用一个值 f（展开 inOutCubic，收回 inOutCubic）插值 left/top/width/height 与圆角；停留期间图片 1→1.07 Ken Burns；f 同时驱动压暗层透明度与 HUD 文字颜色；卡片说明与引线随 f 退场。","trigger":"高光时刻","effect":"从“看地图上的一张照片”无缝进入“身临其境”，再回到地图。","timing":[{"name":"浮入","value":"550ms outCubic：上移 26px、缩放 0.965→1"},{"name":"展开","value":"600ms inOutCubic"},{"name":"停留","value":"约 3s，Ken Burns 1→1.07"},{"name":"收回","value":"550ms inOutCubic"}],"useCases":["影像高光","展示台展品放大","操作台详情查看"],"avoid":["连续多次展开造成疲劳","卡片与全屏图片比例差距过大而又不允许裁切"],"accessibility":{"reducedMotion":"直接切换卡片与全屏，保留压暗层与 HUD。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["corner-hud","vertical-title-blur","split-compare-stamp"],"conflicts":[],"notes":"全屏时只允许一种全屏媒体；参考视频中部分全屏为硬切，Demo 用连续展开示范同一结构。"},"prompt":"实现“卡片 → 全屏 → 卡片”：卡片静止于右侧（宽 min(44vw, 860px)，16:10），550ms outCubic 浮入；在高光时刻用 600ms inOutCubic 把 left/top/width/height 插值到全屏、圆角 6px→0，停留 3s 期间图片 scale 1→1.07，再 550ms 收回。用同一个展开值驱动：上下渐变压暗层透明度、HUD 文字由墨色变白、卡片说明与引线淡出。所有状态由时间 t 计算，可任意 seek。","demo":"demos/patterns/card-expand-fullscreen/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"地图上的照片卡片切换后，于 22.7 秒变为全屏实拍，DAY/时钟等 HUD 保留在画面上；之后回到地图卡片。","evidence":"adapted","locator":"0:20.6–0:23.9"}],"previewAt":1.6,"preview":"previews/patterns/card-expand-fullscreen.jpg","previewPortrait":null},{"id":"chapter-frame","order":15,"title":"章节主题：标签、强调色与四角框线","types":["composition","transition"],"carriers":["video","console","showcase"],"summary":"进入一个主题时，标签色块擦出、标题打字、全局强调色换成主题色，屏幕边缘描出一圈细框并在四角弹出方块——像游戏进入一段任务。","mechanism":"强调色以 400ms 从默认色插值到章节色，并同步到路线、卡片描边、标签与框线；框线是沿屏幕内缘的路径，用 dashoffset 800ms 描出；四角 14px 方块 120ms 错峰 outBack 弹出。离开时整体 500ms 淡出、颜色 600ms 回到默认。","trigger":"进入作品/主题/任务段","effect":"观众立即知道“现在讲的是另一件事”，同时保持同一套系统。","timing":[{"name":"色块擦出","value":"350ms outCubic（clip-path）"},{"name":"强调色","value":"入 400ms / 出 600ms"},{"name":"框线描出","value":"800ms inOutCubic"},{"name":"四角方块","value":"300ms outBack，错峰 120ms"}],"useCases":["多主题旅行影像","游戏任务段落","展示台分区"],"avoid":["主题过多导致色彩失去意义（建议 ≤5 种）"],"accessibility":{"reducedMotion":"框线与颜色直接出现，标题完整显示。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["corner-hud","route-draw-marker","vertical-title-blur"],"conflicts":[],"notes":"全屏回忆有自己的框时，隐藏章节框线避免双框。"},"prompt":"实现章节主题切换：标签色块（强调色底、白色 12px 等宽、字距 .24em）用 clip-path 350ms 从左擦出，旁边标题打字 700ms，再弹出一个 SVG 小图标；全局 CSS 变量 --accent 用 400ms 从默认色插值到章节色，路线、卡片描边、标签与框线都读取它；沿屏幕内缘（inset 8–20px）描一圈 3px 框线，stroke-dashoffset 800ms inOutCubic 从周长到 0，四角 14px 方块 120ms 错峰 outBack 弹出。离开时 500ms 淡出，颜色 600ms 回默认。","demo":"demos/patterns/chapter-frame/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"每部作品出现时：PILGRIMAGE 标签 + 作品名 + 小图标，强调色变为该作品色（蓝/红/紫），屏幕四角框线描出带方块。","evidence":"observed","locator":"0:40.7、1:46.5、2:10.5"}],"previewAt":2.4,"preview":"previews/patterns/chapter-frame.jpg","previewPortrait":null},{"id":"split-compare-stamp","order":16,"title":"分屏对比与时间戳盖章","types":["transition","composition"],"carriers":["video","showcase"],"summary":"先给出“现在”的全屏画面，再让分割线从左边滑到中线露出“过去”，最后一枚倾斜的描边时间戳盖下来。动画结束后可拖动分割线。","mechanism":"左层用 clip-path inset 控制可见宽度，分割线位置 700ms outQuart 从 0 到 50%；两侧标签分别在各自画面出现后淡入；时间戳 380ms outBack 从 1.45 缩到 1、旋转 -4°。交互模式下指针/方向键改变分割百分比。","trigger":"对照时刻（动画 vs 实景、过去 vs 现在、方案 A vs B）","effect":"两张构图对齐的图片形成强烈“同一地点”的确认感。","timing":[{"name":"分割线","value":"700ms outQuart，停在 50%"},{"name":"盖章","value":"380ms outBack，1.45→1，-4°"},{"name":"标签","value":"各自 300ms 淡入"}],"useCases":["巡礼对比","前后改造","设计方案对照","展示台复原对比"],"avoid":["两张图构图不对齐时（对比失去意义）"],"accessibility":{"reducedMotion":"直接停在 50% 分割与盖章完成态。","keyboard":"分割线可聚焦，←/→ 每次移动 5%。"},"composition":{"role":"accent","pairsWellWith":["card-expand-fullscreen","vertical-title-blur","film-grain"],"conflicts":[],"notes":"对比前先给一段任一侧的全屏，让观众记住构图，再揭示另一侧。"},"prompt":"实现分屏对比：两张构图对齐的图片叠放，上层（过去）用 clip-path: inset(0 X% 0 0) 控制可见宽度；分割线 3px 白色带阴影与圆形把手，700ms outQuart 从左边滑到 50%；左右各有 12px 等宽深色标签（如 POSTCARD · 1930s / REAL · 2026）在各自画面出现后淡入；380ms 后一枚 3px 白色描边、等宽粗体的时间戳以 outBack 从 1.45 缩到 1 并旋转 -4° 盖下。动画结束后分割线可拖动、可用方向键调整（role=slider）。","demo":"demos/patterns/split-compare-stamp/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"动画全屏 → 实景全屏 → 分割线从左滑到中线，ANIME · 2015 / REAL · 2026 标签，倾斜描边时间戳 10.01 · 18:20 JST。","evidence":"observed","locator":"1:39.35–1:40.6"}],"previewAt":2.4,"preview":"previews/patterns/split-compare-stamp.jpg","previewPortrait":null},{"id":"collect-counter","order":17,"title":"收集计数徽章与图鉴托盘","types":["feedback","hud"],"carriers":["video","console","showcase"],"summary":"一个吉祥物头像胶囊记录“发现次数”，每次 +1 数字上滚、徽章回弹、外圈扩散；图鉴托盘的空位依次点亮，给叙事加上轻游戏化的奖励感。","mechanism":"计数由事件列表推导（发生时刻 ≤ t 的数量），最后一次事件后的时间 k 驱动：数字 300ms 从下方滚入、整体缩放 1 + 0.14·e^(-7k)、头像外圈放大淡出。托盘槽位按事件依次 420ms outBack 填入缩略图与名字，空位显示虚线与问号。","trigger":"发现/打卡/完成任务","effect":"把重复出现的小元素变成线索与奖励，鼓励观众“找”。","timing":[{"name":"数字滚入","value":"300ms outCubic"},{"name":"回弹","value":"幅度 0.14，衰减系数 7（约 0.5s 收敛）"},{"name":"槽位点亮","value":"420ms outBack，缩放 0.9→1"}],"useCases":["旅行吉祥物出现次数","展会打卡","任务进度","收藏型展示台"],"avoid":["计数与叙事无关时（会显得廉价）"],"accessibility":{"reducedMotion":"数字与槽位直接更新；状态以 aria-live 文本播报。","keyboard":"“+1 发现”与“重置”为原生按钮。"},"composition":{"role":"accent","pairsWellWith":["corner-hud","outro-stat-stack"],"conflicts":[],"notes":"结尾统计里复用同一计数（×N），形成首尾呼应。"},"prompt":"实现收集计数徽章：右上角白色胶囊（头像 + 12px 等宽标签 + 粗体 ×N），计数由事件时刻列表推导；最近一次事件后经过 k 秒时，数字在 300ms 内从下方滚入、徽章 scale(1 + 0.14·e^(-7k))、头像外圈 2px 强调色环放大并淡出。下方图鉴托盘 N 个 3:4 槽位，空位为虚线 + 问号，事件发生时依次 420ms outBack 填入缩略图与名字并换成强调色描边。徽章 role=status 播报当前数量，提供手动 +1 与重置按钮。","demo":"demos/patterns/collect-counter/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"右上角 YUI SPOTTED ×N 随全片递增（×2→×11→×22）；Sound! Euphonium 段落右下角色托盘 REINA / HAZUKI / MIDORI / KUMIKO 依次点亮；结尾统计 ×19 YUI SIGHTINGS。","evidence":"observed","locator":"0:16.5、1:14.5、2:30.5"}],"previewAt":6.2,"preview":"previews/patterns/collect-counter.jpg","previewPortrait":null},{"id":"alert-reroute","order":18,"title":"警示横幅与改道","types":["feedback","hud"],"carriers":["video","console"],"summary":"意外事件用一条红色通栏从左擦入，错误路线画红并以叉号收尾，黑色“改道中…”胶囊闪烁省略号；纠正后换成绿色“已回到路线”。","mechanism":"横幅 clip-path 380ms 从左展开，说明文字随后打字；画面瞬间叠一层 18% 红色乘法闪光并指数衰减；错误路线描画结束时 × 以 outBack 弹出；改道路线用强调色重新描画；恢复时胶囊图标与文字替换并轻微回弹，错误路线降为 35% 透明度保留痕迹。","trigger":"意外 / 错误 / 系统告警","effect":"节奏里的“转折”，制造小小紧张感并立刻给出解决。","timing":[{"name":"横幅擦入","value":"380ms outCubic"},{"name":"红色闪光","value":"18% → 0，约 350ms 衰减"},{"name":"胶囊省略号","value":"每 333ms 增加一个点"},{"name":"错误路线淡化","value":"600ms 降到 35%"}],"useCases":["旅行意外","物流异常","操作台告警","游戏任务失败/重试"],"avoid":["频繁告警（会削弱紧张感）"],"accessibility":{"reducedMotion":"无闪光，横幅直接出现。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"accent","pairsWellWith":["route-draw-marker","corner-hud"],"conflicts":[],"notes":"告警期间暂停其他事件层，避免两条横幅同时出现。"},"prompt":"实现“警示 + 改道”：红色通栏（#e5483b，带 1px/3px 横向扫描纹理）从左 380ms clip-path 擦入，内容为 SVG 警示图标 + 粗体字距 .14em 的标题 + 12px 等宽说明（打字）；画面同时叠加 18% 红色 multiply 闪光并在 350ms 内衰减。地图上错误路线画红、末端弹出 ×；下方黑色胶囊“REROUTING”带 SVG 双左箭头，省略号每 333ms 加一点。改道路线用强调色重新描出；恢复时胶囊变绿、图标换成对勾并回弹，错误路线 600ms 降至 35% 透明度。","demo":"demos/patterns/alert-reroute/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"红色通栏 ⚠ WRONG TRAIN + 线路说明，黑色 ◀◀ REROUTING… 胶囊，错误路线红色并以叉号收尾。","evidence":"observed","locator":"2:08.5"}],"previewAt":2.6,"preview":"previews/patterns/alert-reroute.jpg","previewPortrait":null},{"id":"outro-stat-stack","order":19,"title":"结尾数据堆叠与计数","types":["type-motion","rhythm"],"carriers":["video","showcase"],"summary":"大号数字逐行出现并快速计数，右侧配等宽小字标签，最后以衬线“— fin.”与署名收束；像游戏结算界面，给旅程一个“分数”。","mechanism":"每行错峰 320ms，450ms 上移淡入；数字 900ms outQuart 从 0 计到目标值（前段快速跳数、末尾放慢落定），支持前缀 × 与后缀 km；结尾文字逐字模糊入场（60ms 错峰），致谢最后淡入。","trigger":"片尾 / 展示结束","effect":"把叙事中的线索（天数、地点、计数）总结成可感知的成就。","timing":[{"name":"行错峰","value":"320ms"},{"name":"计数","value":"900ms outQuart，千分位格式"},{"name":"fin.","value":"逐字 500ms，错峰 60ms，模糊 12px"}],"useCases":["影像片尾","年度回顾","活动战报","展示台结束页"],"avoid":["数字没有实际意义时（会显得空洞）"],"accessibility":{"reducedMotion":"数字直接显示最终值。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["collect-counter","corner-hud"],"conflicts":[],"notes":"背景保留全程鸟瞰地图或路线，数字与路线互相印证。"},"prompt":"实现片尾数据堆叠：左侧垂直列表，每行“大号数字（DIN 类 800 字重，34–86px，等宽数字）+ 12px 等宽标签（字距 .22em）”；第 i 行在 t0 + i×320ms 以 450ms 上移 14px 淡入，数字 900ms outQuart 从 0 计数到目标值（支持“×”前缀与“ km”后缀、千分位）。最后一行下方用衬线体写“标题 — fin.”，逐字 60ms 错峰模糊入场，再淡入署名与 12px 致谢。背景保留淡化的完整路线。","demo":"demos/patterns/outro-stat-stack/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"7 DAYS · 2 COUNTRIES / 5 WORKS VISITED / 3 NOTES LEFT / ×19 SIGHTINGS / 1,159 km + 衬线「聖地巡礼 — fin.」与署名、音乐与动画出处。","evidence":"observed","locator":"2:30.5"}],"previewAt":4.2,"preview":"previews/patterns/outro-stat-stack.jpg","previewPortrait":null},{"id":"seekable-timeline","order":20,"title":"可逐帧定位的时间轴","types":["rhythm"],"carriers":["video","console","showcase"],"summary":"把画面写成 render(t) 纯函数、把所有时间写进轨道：同一份代码既能实时播放，也能被拖动、跳到节拍，或逐帧截图渲染成视频。","mechanism":"MotionKit.timeline({duration, render}) 管理播放与 seek；所有动画用 seg/env/keyframes 从 t 推导，不用 setTimeout/CSS 动画；随机数用固定种子、颗粒按帧号选帧；expose() 暴露 window.__motion 供站点刻度条与 scripts/render.mjs 使用；?render=1 时 seek 可等待异步资源（如地图瓦片）。","trigger":"播放 / 拖动 / 逐帧渲染","effect":"节奏可精确调整到每一帧，影像与交互共用一套代码。","timing":[{"name":"协议","value":"window.__motion = { duration, markers, seek(t)→Promise, play, pause, on }"},{"name":"URL","value":"?embed 隐藏控制条 · ?render 关闭自动播放 · ?t=秒 定位"},{"name":"渲染","value":"node scripts/render.mjs <url> --fps 30 → PNG 序列（有 ffmpeg 时合成 MP4）"}],"useCases":["程序化视频生成","可回放的展示台","需要精确节奏调试的任何动效"],"avoid":["依赖真实用户输入、不可预测的物理模拟（需另行录制）"],"accessibility":{"reducedMotion":"不自动播放；时间轴可手动拖动查看。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"foundation","pairsWellWith":["film-grain","corner-hud"],"conflicts":[],"notes":"交互型作品可只对“演示模式”使用时间轴，真实交互仍走事件驱动。"},"prompt":"用“时间轴纯函数”组织这段动效：定义 CONFIG.tracks（每条轨道是按时间排列的事件/关键帧），写 render(t) 只根据 t 计算全部 DOM/Canvas 状态（进度用 clamp((t-start)/dur) 再套缓动；关键帧之间插值），禁止 setTimeout、CSS animation 与 Math.random()（改用固定种子随机数，颗粒按 floor(t×fps) 选帧）。用 timeline 控制播放/暂停/seek，并暴露 window.__motion = { duration, markers, seek(t)→Promise, play, pause, on(fn) }；支持 ?embed 隐藏控制条、?render=1 关闭自动播放（seek 等待异步资源完成）、?t=秒 直接定位；空格/方向键控制播放与跳转。","demo":"demos/patterns/seekable-timeline/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"参考视频由 Agent 程序化剪辑而成，画面元素与时间高度对齐；本库以 render(t) 协议复现，以便拖动、跳拍与逐帧渲染。","evidence":"adapted","locator":"全片"}],"previewAt":2.8,"preview":"previews/patterns/seekable-timeline.jpg","previewPortrait":null},{"id":"film-grain","order":21,"title":"可复现的胶片颗粒与暗角","types":["texture"],"carriers":["video","showcase","console"],"summary":"预生成几帧噪声、按帧号选帧叠加，配合暗角、扫描线与轻微闪烁；同一时刻永远是同一张颗粒，逐帧渲染也不会“跳”。","mechanism":"320×180 的噪声画布放大覆盖全屏（image-rendering: pixelated），mix-blend-mode: overlay；frames 帧循环，帧号 = floor(t × fps)；闪烁亮度用以帧号为种子的伪随机；暗角是径向渐变；扫描线是 1px/3px 重复渐变。回忆段把强度从 0.07 提到 0.15 左右。","trigger":"常驻 / 回忆段加重","effect":"数码画面有了“胶片/录像”的质感，并把不同来源的素材统一在一起。","timing":[{"name":"强度","value":"常态 0.07–0.12，回忆 0.15–0.25（overlay）"},{"name":"换帧","value":"12fps，6 帧循环"},{"name":"暗角","value":"0.3–0.45"},{"name":"闪烁","value":"±4% 亮度"}],"useCases":["影像统一质感","回忆/档案段","复古操作台"],"avoid":["需要高清细节的产品图","大量小字区域（降低可读性）"],"accessibility":{"reducedMotion":"颗粒停在一帧，关闭闪烁。","keyboard":"参数面板为原生滑杆。"},"composition":{"role":"support","pairsWellWith":["seekable-timeline","split-compare-stamp"],"conflicts":[],"notes":"颗粒放在所有层之上但不拦截指针；HUD 小字区域保持低强度。"},"prompt":"叠加可复现的胶片颗粒：预生成 6 帧 320×180 灰度噪声（固定种子），放在全屏 canvas 上（image-rendering: pixelated，mix-blend-mode: overlay，pointer-events: none），每帧显示 frames[floor(t×12) % 6]，透明度常态 0.07–0.12、回忆段 0.2；加 0.3–0.45 的径向暗角、可选 1px/3px 扫描线；亮度闪烁 ±4% 用 rng(帧号) 计算而不是 Math.random()。提供强度/fps/暗角/扫描线/闪烁五个滑杆。","demo":"demos/patterns/film-grain/index.html","kit":true,"sources":[{"caseId":"map-pilgrimage","observation":"全片带轻颗粒，动画回忆段颗粒明显加重，实景与动画素材因此统一。","evidence":"observed","locator":"0:22.7、0:55.2"}],"previewAt":1.2,"preview":"previews/patterns/film-grain.jpg","previewPortrait":null},{"id":"boot-typing","order":30,"title":"终端逐字开机序列","types":["type-motion","rhythm","sound"],"carriers":["console","video","showcase"],"summary":"白场上逐字输入请求、停顿、黑底闪一下再清空，圆环与标志随后绘出，身份确认三行错峰打字——用“输入的节奏”建立系统的可信度。","mechanism":"预先计算每个字符的出现时刻（每字间隔 + 指定字符后的停顿），渲染与音效共用同一份时刻表；行完成时黑底反色闪 180ms 后清空；圆环用 stroke-dashoffset 依次描出，标志笔画随后显现；光标在输入中常亮、完成后闪烁。逐字短音三种音高轮替，并限制最短间隔防止叠音。","trigger":"页面载入 / 重新初始化","effect":"在任何内容出现前先建立“系统正在启动、正在识别你”的仪式感。","timing":[{"name":"每字间隔","value":"45ms（身份行 30–32ms）"},{"name":"停顿","value":"冒号后 250–350ms，省略号每点 120ms"},{"name":"反色闪","value":"180ms"},{"name":"圆环","value":"900ms inOutCubic，第二环延迟 450ms"},{"name":"短音","value":"38ms 方波，三音高轮替，最短间隔 24ms"}],"useCases":["操作台/终端开机","游戏内系统登录","发布会开场","展示台待机唤醒"],"avoid":["每次访问都强制观看（提供跳过与只播放一次）"],"accessibility":{"reducedMotion":"直接显示完整文字与标志，不做逐字与闪烁。","keyboard":"空格播放/暂停；提供跳过入口。"},"composition":{"role":"support","pairsWellWith":["rolling-digits","decrypt-reveal","wave-array"],"conflicts":[],"notes":"开机层结束时整体失焦、缩小并淡出，让下一层自然接管。"},"prompt":"实现终端逐字开机序列：先按“每字间隔 + 特定字符后停顿”预计算每个字符的出现时刻（如每字 45ms、冒号后停 350ms），渲染与音效共用这份时刻表；输入中显示块状光标，完成后黑底反色闪 180ms 再清空；随后两个圆环以 stroke-dashoffset 900ms 依次描出（第二环延迟 450ms），标志笔画显现；再错峰打出三行身份确认（每字 30ms）。逐字短音用 38ms 方波、三种音高轮替、最短间隔 24ms，默认静音。全部是时间 t 的纯函数，提供跳过与减少动态下的静态完成态。","demo":"demos/patterns/boot-typing/index.html","kit":true,"previewAt":6.4,"sources":[{"caseId":"archive-os","observation":"逐字输入、停顿、清空、闪切固定到原片帧点；标志从右上弧线开始绘制、绕左环再补全右环；身份段 ID CONFIRMED / REQUEST RECEIVED / START PROCESSING；逐字输入音为原片三个 38ms 短音轮替，最短间隔 24ms。","evidence":"observed","locator":"DESIGN.md · 启动前段逐帧修订 / 原片逐字输入音效复刻"}],"preview":"previews/patterns/boot-typing.jpg","previewPortrait":null},{"id":"rolling-digits","order":31,"title":"滚动数字与文字","types":["type-motion","feedback"],"carriers":["console","showcase","video"],"summary":"编号、计数、标题与分类在切换时沿输入方向滚动 460ms，带极轻的运动模糊；快速连按只显示“当前运动 → 最新目标”，不为中间值排队。","mechanism":"每个数字位是一个裁切窗口，旧字符与新字符上下排列，按进度 p 平移一格；只有变化的位才滚动。文字（含中文）整行替换：旧行沿方向滚出并淡出，新行从反方向滚入。方向跟随输入（下一项向上滚、上一项向下滚）。连续输入时从上一个目标重新起滚。","trigger":"切换选择 / 数值更新","effect":"数字的变化有方向和重量，用户能“感觉”到自己往哪个方向翻动。","timing":[{"name":"时长","value":"460ms outCubic"},{"name":"运动模糊","value":"sin(pπ)×0.35px"},{"name":"方向","value":"下一项向上滚，上一项向下滚"}],"useCases":["档案编号","计数器与页码","时钟","分类标题切换"],"avoid":["大段文字","每秒变化很多次的实时数据（改为直接替换）"],"accessibility":{"reducedMotion":"立即显示最终值。","keyboard":"按钮为原生 button，带可访问名称；数值区域 aria-live。"},"composition":{"role":"accent","pairsWellWith":["wave-array","boot-typing","corner-hud"],"conflicts":[],"notes":"编号、标题、列名共用同一个时长与方向，看起来是同一次“翻动”。"},"prompt":"实现方向感滚动数字与文字：每个数字位是 height:1em 的 overflow:hidden 窗口，内部上下排列旧字符与新字符，按进度 p（460ms outCubic）平移一格，只有变化的位滚动，并加 sin(pπ)×0.35px 的运动模糊；文字整行替换，旧行沿方向滚出淡出、新行反方向滚入。方向由输入决定（下一项向上、上一项向下）。快速连按时从上一个目标重新起滚，不排队播放中间值。减少动态时直接替换。","demo":"demos/patterns/rolling-digits/index.html","kit":true,"previewAt":3.85,"sources":[{"caseId":"archive-os","observation":"主档案标题与编号共享 460ms 滚动配置，固定向上滚动、模糊强度 0.2；连续输入从当前运动接续，只显示可见过渡与最新目标；底部列名、悬停标题与权限标签复用同一滚动。","evidence":"observed","locator":"DESIGN.md · 档案标题滚动 / 档案导航文字与刻度"}],"preview":"previews/patterns/rolling-digits.jpg","previewPortrait":null},{"id":"decrypt-reveal","order":32,"title":"对角解密与磨砂转清","types":["transition","texture"],"carriers":["console","showcase","video"],"summary":"两条信号色对角线合拢、停留、收束；玻璃盖板自上而下由磨砂变清晰；右侧文档上的黑色遮挡条按阅读顺序依次退开——“读取”被做成一个可以看见的过程。","mechanism":"对角线是两条 SVG 路径（vector-effect: non-scaling-stroke），用 dashoffset 从 0 到全长再到负值实现“合拢→收束”；磨砂层是 backdrop-filter: blur 的覆盖层，用 clip-path: inset(p% 0 0 0) 自上而下切掉，并有一条高光边沿跟随；每个文本块内放一条绝对定位的黑色遮挡条，transform-origin 右侧，scaleX 1→0，按 80ms 错峰。","trigger":"打开档案 / 解锁内容","effect":"把等待变成揭示，内容的价值感与保密感同时成立。","timing":[{"name":"对角线","value":"合拢 450ms inOutCubic，约 1.1s 后收束 350ms"},{"name":"转清","value":"1.3s inOutCubic，自上而下"},{"name":"遮挡条","value":"每条 420ms，错峰 80ms，从标题到摘要"}],"useCases":["档案/资料详情","解锁奖励","产品规格揭示","保密信息展示"],"avoid":["频繁打开的列表详情（每次都揭示会拖慢效率，可只在首次）"],"accessibility":{"reducedMotion":"直接显示清晰内容与正文。","keyboard":"揭示不阻挡焦点；正文在 DOM 中始终可读。"},"composition":{"role":"support","pairsWellWith":["boot-typing","rolling-digits","card-flip-sheen"],"conflicts":[],"notes":"遮挡条只覆盖视觉，正文文字始终在 DOM 中，屏幕阅读器不受影响。"},"prompt":"实现“解密揭示”：左侧玻璃卡（圆角 16px、半透明暖白、内含 SVG 结构图），其上覆盖 backdrop-filter: blur(9px) 的磨砂层；两条信号色对角线（SVG，non-scaling-stroke）用 stroke-dasharray 142 在 450ms 内合拢，停留约 1.1s 后 350ms 收束；磨砂层用 clip-path: inset(p% 0 0 0) 在 1.3s 内自上而下切掉，并有一条渐变高光沿切口移动；右侧文档每个文本块（标题、分类、四项元数据、摘要）内置一条黑色遮挡条，transform-origin 右侧、scaleX 1→0，每条 420ms、按阅读顺序错峰 80ms。正文始终在 DOM 中可读；减少动态时直接显示完成态。","demo":"demos/patterns/decrypt-reveal/index.html","kit":true,"previewAt":1.6,"sources":[{"caseId":"archive-os","observation":"模型与正文同步解密：对角解密线合拢、保持并收束，盖板自上而下由磨砂变清晰；右侧文档的遮挡条随之退开，露出标题、资料字段与正文。","evidence":"observed","locator":"README · 新版效果"}],"preview":"previews/patterns/decrypt-reveal.jpg","previewPortrait":null},{"id":"wave-array","order":33,"title":"阵列选择波浪","types":["feedback","rhythm"],"carriers":["console","showcase"],"summary":"在一整片重复元素中选中一个：它以临界阻尼抬起，同时向四周传出一圈按距离延迟、指数衰减的余波——选择像投入水面的石子。","mechanism":"每块的高度 = 选中抬起（临界阻尼阶跃，取消选中时以当时高度衰减回落）+ 最近三次选择的余波之和；余波 z = A·sin(ωτ)·e^(−kτ)/(1+f·d)，τ = t − t₀ − delay·d，d = 行距 + 0.8×列距。全部是事件序列在时刻 t 的解析函数，可快速反向、可 seek。","trigger":"选择变化（键盘/点击）","effect":"整片阵列都对一次选择作出反应，焦点清晰且有“物理”感。","timing":[{"name":"抬起","value":"临界阻尼速率 4.2，26px"},{"name":"余波","value":"A 9–10px · ω 7.5 · k 2.6 · 延迟 70ms/格 · 距离衰减 0.35"},{"name":"叠加","value":"只叠加最近 3 次选择，避免长期累积"}],"useCases":["档案/卡片阵列","音乐可视化选择","商品墙","游戏关卡选择"],"avoid":["元素少于 9 个（余波不明显）","需要精确对齐阅读的表格"],"accessibility":{"reducedMotion":"只抬起选中块，不发余波。","keyboard":"方向键移动选择，点击块直接选择。"},"composition":{"role":"foundation","pairsWellWith":["rolling-digits","idle-breathing"],"conflicts":[],"notes":"余波幅度要小于块间距，避免互相穿插；选中块的抬起与余波同时开始。"},"prompt":"实现阵列选择波浪：CSS 3D（perspective 1500px，rotateX 58° rotateZ -36°）排列 7×9 块（顶/正/侧三面），每块 translateZ 由解析函数计算：选中块 z += L·(1 − (1 + wτ)e^(−wτ))（w=4.2，L=26px），取消选中后以当时高度按 (1 + wτ)e^(−wτ) 回落；对最近 3 次选择，其他块 z += 10·sin(7.5τ)·e^(−2.6τ)/(1 + 0.35d)，τ = t − t₀ − 0.07d，d = |Δ行| + 0.8|Δ列|。方向键与点击产生选择事件；整个状态由事件序列在时刻 t 推导，可 seek。透明度不要加在 preserve-3d 容器上。","demo":"demos/patterns/wave-array/index.html","kit":true,"previewAt":2.55,"sources":[{"caseId":"archive-os","observation":"选中卡片两侧在回传后继续起伏，按距选中位置的距离延迟并衰减；用户对比后确认采用原始基线：完整正负波谷的选中波浪，选中与波浪同时开始，升降阻尼速率 4.2。","evidence":"observed","locator":"DESIGN.md · 参考与既有规范 / 当前采用：原始基线动效"}],"preview":"previews/patterns/wave-array.jpg","previewPortrait":null},{"id":"idle-breathing","order":34,"title":"空闲呼吸","types":["rhythm"],"carriers":["console","showcase"],"summary":"停止操作 2.5 秒后，界面元素以两个不成整数比的周期（8s 与 13s）叠加缓慢起伏，相邻元素错相；任何操作立即渐退——界面“活着”，但不打扰。","mechanism":"空闲时长 = t − 最后一次输入；强度 = clamp((空闲 − 2.5) / 1.5)；位移 = 强度 × A × (0.6·sin(2πt/8 + iφ₁) + 0.4·sin(2πt/13 + iφ₂))。两个周期不成整数比，叠加后长时间不重复；相位按元素索引偏移形成“流动”。","trigger":"一段时间无操作","effect":"静止画面里保有生命感，暗示“系统在等待你”。","timing":[{"name":"阈值","value":"2.5s 后开始，1.5s 渐入"},{"name":"周期","value":"8s 与 13s，权重 0.6 / 0.4"},{"name":"幅度","value":"约元素高度的 2–3%（Demo 14px 为演示放大）"},{"name":"退出","value":"任何输入立即开始渐退"}],"useCases":["待机画面","展示台/壁纸","游戏菜单","操作台空闲态"],"avoid":["用户正在阅读或比较数值时","可能引起眩晕的大幅运动"],"accessibility":{"reducedMotion":"完全关闭呼吸。","keyboard":"任何按键都会打断呼吸。"},"composition":{"role":"support","pairsWellWith":["wave-array","rolling-digits"],"conflicts":[],"notes":"呼吸与选择余波可以叠加，但呼吸强度在操作时为 0，避免两者同时明显。"},"prompt":"实现空闲呼吸：记录最后一次输入时刻；强度 = clamp((t − last − 2.5) / 1.5)；第 i 个元素位移 = 强度 × A × (0.6·sin(2πt/8 + 1.3i) + 0.4·sin(2πt/13 + 0.7i))，A 取元素高度的 2–3%；任何输入立即让强度归零（或在 300ms 内渐退）；prefers-reduced-motion 时完全关闭。附一个空闲计量条与呼吸曲线可视化便于调参。","demo":"demos/patterns/idle-breathing/index.html","kit":true,"previewAt":6.5,"sources":[{"caseId":"archive-os","observation":"交互预览停止操作 2.5 秒后渐入呼吸起伏：8 秒与 13 秒周期叠加，最大单向位移约卡片高度的 2.8%，相邻卡片略微错相；切换档案、进入详情或开启减少动态效果时渐退。","evidence":"observed","locator":"DESIGN.md · 最新交互修订"}],"preview":"previews/patterns/idle-breathing.jpg","previewPortrait":null},{"id":"skew-menu","order":40,"title":"斜切指令菜单","types":["feedback","composition"],"carriers":["console","showcase"],"summary":"每个菜单项都是一块斜切的白板加一块偏移的黑影；选中时以“吸附”缓动放大、扭转并黑白反转，影子持续小幅抖动——静止的菜单也在呼吸与挑衅。","mechanism":"菜单项静止角度错落（−5°~+3°）；选中/离开用同一个 0→1 进度驱动 translateX、rotate、scale（snap 缓动 160ms）；选中项 plate 与 shadow 颜色互换，shadow 位移叠加两个不同频率的正弦形成抖动；z-index 提升避免被邻项遮挡。","trigger":"光标移动 / 悬停 / 聚焦","effect":"当前选项极其醒目，菜单本身成为视觉表演的一部分。","timing":[{"name":"切换","value":"160ms snap（cubic-bezier(.2,.9,.1,1)）"},{"name":"选中形变","value":"scale 1.18 · rotate −7° · 右移 26px"},{"name":"影子抖动","value":"±3px，31Hz / 27Hz"},{"name":"静止角度","value":"−5° ~ +3° 错落"}],"useCases":["游戏主菜单/战斗指令","活动页导航","直播互动菜单"],"avoid":["需要稳定扫读的长列表","对动态敏感的场景（关闭抖动）"],"accessibility":{"reducedMotion":"保留放大与反色，关闭影子抖动。","keyboard":"原生按钮，↑/↓ 移动焦点，焦点即选中。"},"composition":{"role":"foundation","pairsWellWith":["ransom-type","impact-pop","cutin-slash"],"conflicts":[],"notes":"背景需要大块对角线（黑带）来承接倾斜的菜单，否则会显得歪而不是酷。"},"prompt":"实现斜切指令菜单：每项是一个按钮，内部两层 clip-path 斜切多边形——白色板与向右下偏移 10px/8px 的黑色影子，上面是 26–64px 超粗标签与小字中文；各项静止角度错落（如 −4°, 2°, −2°, 3°, −5°）。选中时用 160ms cubic-bezier(.2,.9,.1,1) 把 translateX 0→26px、rotate 加 −7°、scale 1→1.18，板与影子黑白互换、文字反白；选中项影子位移叠加 sin(31t)·3px 与 cos(27t)·3px 的抖动。悬停、聚焦、↑/↓ 都会选中。减少动态时关闭抖动。","demo":"demos/patterns/skew-menu/index.html","kit":true,"previewAt":2.2,"sources":[{"caseId":"phantom-battle","observation":"暂停菜单悬停项放大并变色（与红黑白主色对比）；战斗行动围绕当前角色排布并以按键颜色区分。","evidence":"inferred","locator":"Mechanics of Magic 分析"}],"preview":"previews/patterns/skew-menu.jpg","previewPortrait":null},{"id":"cutin-slash","order":41,"title":"角色切入斜带","types":["transition"],"carriers":["video","console"],"summary":"一条倾斜的黑带夹着红带从画面一侧极快切入，内含流动的速度线与眼部特写，文字逐字拍上，停留约一秒后继续从另一侧离场——战斗中的“高光插播”。","mechanism":"外层黑带旋转 −8° 并溢出画面两侧，translateX 由 120% → 0（220ms outExpo）→ −120%（220ms inCubic）；内层红带的重复线性渐变背景按时间平移形成速度线；特写 SVG 在停留期缓推 12%；切入瞬间反色闪 60ms 与指数衰减抖动。","trigger":"连击 / 额外回合 / 必杀前","effect":"打断常规节奏的一次“强调”，把角色情绪推到最前。","timing":[{"name":"切入","value":"220ms outExpo"},{"name":"停留","value":"约 1.3–1.6s"},{"name":"离场","value":"220ms inCubic，同方向继续"},{"name":"速度线","value":"1400px/s"},{"name":"缓推","value":"停留期 +12%"}],"useCases":["战斗连击","直播高光","体育进球插播","发布会角色介绍"],"avoid":["每分钟多次（会失去冲击力）"],"accessibility":{"reducedMotion":"无闪光与抖动，斜带直接出现与消失。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"accent","pairsWellWith":["ransom-type","impact-pop","stinger-bars"],"conflicts":["shape-wipe"],"notes":"与异形遮罩不要紧挨着使用：两个“全屏强调”连续出现会互相削弱。"},"prompt":"实现角色切入斜带：一条宽度 130%、高度约 36% 的黑色带（rotate −8°）内嵌上下各留 13% 的红色带；红带背景是 repeating-linear-gradient 速度线，backgroundPosition 随时间以 1400px/s 平移；中间放角色眼部特写 SVG。切入：translateX 120%→0，220ms outExpo，同时 60ms 反色闪（mix-blend-mode: difference）与 12px·e^(−10t) 屏幕抖动；停留 1.4s 期间特写 scale 1→1.12；离场：继续向左 translateX 0→−120%，220ms inCubic。文字用剪报拼贴字在切入后 150ms 逐字拍入。","demo":"demos/patterns/cutin-slash/index.html","kit":true,"previewAt":1,"sources":[{"caseId":"phantom-battle","observation":"额外回合与总攻前的角色特写切入、倾斜构图与速度线；时长为本地拟合，待实机逐帧核对。","evidence":"inferred","locator":"常见战斗演出 · 待核验"}],"preview":"previews/patterns/cutin-slash.jpg","previewPortrait":null},{"id":"ransom-type","order":42,"title":"剪报拼贴字","types":["composition","type-motion"],"carriers":["video","console","showcase"],"summary":"每个字母像从不同报纸上剪下：独立的底色/字色、字体、字重、角度、大小和上下偏移，并以错峰“拍”进来；固定种子保证每次一致。","mechanism":"用固定种子随机数为每个字符抽取：配色组合（黑底白字/白底黑字/红底白字等）、字体（粗黑体/衬线/打字机/窄体/中文黑体/宋体）、字重、旋转 ±9°、缩放 0.86–1.24、上下偏移 ±0.08em。入场：每字 220ms outBack，从 2.2 倍缩回，旋转从 2 倍角度回到目标角度，30–35ms 错峰。整行文字放在 aria-label 中，字母 span 对读屏隐藏。","trigger":"标题出现 / 关键提示","effect":"叛逆、手作、街头感，同时字形差异让每个字母都值得被看一眼。","timing":[{"name":"入场","value":"每字 220ms outBack，2.2→1"},{"name":"错峰","value":"30–35ms"},{"name":"旋转","value":"±9°"},{"name":"缩放","value":"0.86–1.24"}],"useCases":["游戏标题与提示","潮流海报","音乐节/综艺包装","活动主视觉"],"avoid":["正文与长句","需要品牌字体严格统一的场景"],"accessibility":{"reducedMotion":"直接显示拼贴结果，不做拍入。","keyboard":"输入框与按钮可重新拼贴；整句通过 aria-label 朗读。"},"composition":{"role":"accent","pairsWellWith":["skew-menu","cutin-slash","impact-pop"],"conflicts":[],"notes":"同屏只放一到两组拼贴字；其余文字用统一的粗黑体，形成对比。"},"prompt":"实现剪报拼贴字组件 ransom(el, text, seed)：用固定种子随机数为每个字符生成 span，独立设置配色组合（[黑,白]、[白,黑]、[红,白]、[白,红]、[黑,红]、[米,黑]）、字体（Arial Black / Georgia / Courier New / Impact / Bahnschrift / 中文黑体 / 宋体）、字重 600/900、旋转 ±9°、缩放 0.86–1.24、上下偏移 ±0.08em，内边距 .05em .12em；空格为 .35em 空白。入场时每个字母 220ms outBack 从 2.2 倍缩回、角度从 2 倍回到目标，错峰 35ms。整句写进容器 aria-label，字母 aria-hidden。","demo":"demos/patterns/ransom-type/index.html","kit":true,"previewAt":3.5,"sources":[{"caseId":"phantom-battle","observation":"菜单字体借鉴性手枪乐队专辑封面的剪报拼贴字（媒体转述设计访谈）。","evidence":"inferred","locator":"设计访谈转述"}],"preview":"previews/patterns/ransom-type.jpg","previewPortrait":null},{"id":"impact-pop","order":43,"title":"冲击字弹出","types":["feedback","type-motion"],"carriers":["console","video"],"summary":"命中瞬间先给反色闪、目标后坐与屏幕抖动，随后“WEAK / CRITICAL”从 2.6 倍以回弹落定、倾斜 −10°，背后一圈星芒爆开——反馈的层次比文字本身更重要。","mechanism":"时间以“最近一次命中后经过的秒数”计算：0–60ms 反色闪（difference 混合）；目标位移 40·e^(−6t)；屏幕抖动 22·e^(−12t)（多次命中叠加）；80ms 后文字 260ms outBack 2.6→1，旋转从 −30° 回到 −10°；星芒半径 300ms outExpo 扩张并淡出；文字停留约 0.9s 后 180ms 放大淡出。","trigger":"命中 / 暴击 / 弱点","effect":"让玩家在 0.3 秒内读到“效果很好”，并且身体上感受到打击。","timing":[{"name":"反色闪","value":"60ms"},{"name":"抖动","value":"22px·e^(−12t)"},{"name":"文字","value":"延迟 80ms，260ms outBack，2.6→1，−10°"},{"name":"停留/离场","value":"0.9s / 180ms"}],"useCases":["战斗命中","游戏化反馈（答对/连击）","直播打赏特效"],"avoid":["光敏场景（关闭反色闪）","连续高频触发"],"accessibility":{"reducedMotion":"关闭抖动与闪光，文字直接出现。","keyboard":"“再打一下”为原生按钮；文字区域 role=status。"},"composition":{"role":"accent","pairsWellWith":["skew-menu","cutin-slash","ransom-type"],"conflicts":[],"notes":"冲击字放在目标的左下方，避免遮住目标本身的受击反应。"},"prompt":"实现命中冲击字：记录命中时刻 h，s = t − h。0–60ms 全屏白色 difference 反色闪；目标 translateX 40·e^(−6s)、旋转 8·e^(−6s)、前 100ms brightness(3)；屏幕抖动幅度为所有命中的 22·e^(−12s) 之和，位移取 sin(93t)、cos(71t)。80ms 后冲击字（白字、5px 黑描边 paint-order: stroke、8px 黑色硬投影；暴击用黄色）在 260ms 内 outBack 从 2.6 倍缩到 1、角度从 −30° 回到 −10°；背后白色 14 角星芒 300ms outExpo 扩张并淡出；停留 0.9s 后 180ms 放大淡出。减少动态时只保留文字。","demo":"demos/patterns/impact-pop/index.html","kit":true,"previewAt":0.75,"sources":[{"caseId":"phantom-battle","observation":"命中弱点、暴击时的大号倾斜提示字与爆发图形；时长为本地拟合。","evidence":"inferred","locator":"常见战斗反馈 · 待核验"}],"preview":"previews/patterns/impact-pop.jpg","previewPortrait":null},{"id":"shape-wipe","order":44,"title":"异形遮罩转场","types":["transition"],"carriers":["video","console","showcase"],"summary":"用星芒、锯齿、斜切或圆形的黑色遮罩从中心旋转放大吞没画面，在完全覆盖的瞬间换场，再缩回释放——形状本身就是情绪。","mechanism":"SVG 全屏遮罩（viewBox −50…50，preserveAspectRatio slice）中放一个路径，scale 从 0 到覆盖值（约 3.2，inQuad 加速吞没）→ 换场 → 从覆盖值回到 0（outCubic 减速释放）；整个过程持续旋转。形状可替换：16 角星、锯齿、斜切平行四边形、圆。","trigger":"进入特殊模式 / 场景切换","effect":"比淡入淡出更有个性，转场本身传达风格。","timing":[{"name":"吞没","value":"380ms inQuad"},{"name":"释放","value":"300–320ms outCubic"},{"name":"旋转","value":"90°/s"},{"name":"覆盖倍数","value":"约 3.2（随形状尖角深度调整）"}],"useCases":["进入总攻/必杀","游戏关卡切换","直播场景切换","品牌转场"],"avoid":["频繁切换的界面导航（会疲劳）"],"accessibility":{"reducedMotion":"不旋转；可改为直接切换。","keyboard":"形状选择按钮为原生 button。"},"composition":{"role":"support","pairsWellWith":["ransom-type","impact-pop"],"conflicts":["cutin-slash"],"notes":"遮罩颜色用风格主色（黑），换场在完全覆盖帧发生，避免露出两个场景的叠加。"},"prompt":"实现异形遮罩转场：全屏 SVG（viewBox=\"-50 -50 100 100\"，preserveAspectRatio=\"xMidYMid slice\"，pointer-events none）内放一个黑色路径（16 角星：外径 50、内径 21）。tIn 开始 380ms inQuad 把 scale 0→3.2，同时 rotate 90°/s；在完全覆盖时切换底下的场景；随后 300ms outCubic 把 scale 3.2→0 释放。提供锯齿、斜切、圆三种可替换形状。减少动态时不旋转。","demo":"demos/patterns/shape-wipe/index.html","kit":true,"previewAt":0.85,"sources":[{"caseId":"phantom-battle","observation":"进入总攻等特殊演出时使用的星形/异形遮罩转场；形状与时长为本地拟合，待核验。","evidence":"inferred","locator":"常见战斗转场 · 待核验"}],"preview":"previews/patterns/shape-wipe.jpg","previewPortrait":null},{"id":"chamfer-panel","order":50,"title":"切角工业面板","types":["composition"],"carriers":["console","showcase"],"summary":"用 45° 切角、四角十字注册标记、刻度尺、安全黄三角角标和危险斜纹，把普通矩形面板变成“设备铭牌”；入场时切角从夸张收拢到标准尺寸。","mechanism":"clip-path 多边形实现对角两处切角（或文件夹标签式台阶切口）；切角尺寸用 CSS 变量 --cut 控制，入场时从 134px 以 snap 缓动收拢到 14px；注册标记由两条 2px 线组成；刻度尺是 1px/8px 重复渐变；危险条纹为 −45° 黄黑重复渐变。","trigger":"面板出现 / 常驻","effect":"统一的“工业设备”质感，信息块之间有清晰的边界与层级。","timing":[{"name":"切角","value":"标准 12–16px；入场从 +120px 收拢"},{"name":"入场","value":"450ms snap，面板错峰 120ms"},{"name":"附件","value":"注册标记/刻度/角标在面板就位后 250ms 起错峰 40ms 出现"}],"useCases":["工业/科幻操作台","游戏系统界面","数据大屏","品牌化后台"],"avoid":["需要柔和亲切感的产品"],"accessibility":{"reducedMotion":"面板直接显示标准切角。","keyboard":"纯视觉容器，不影响内部控件的焦点顺序。"},"composition":{"role":"foundation","pairsWellWith":["text-scramble","scanline-wipe","hold-confirm"],"conflicts":[],"notes":"切角只做在对角两处，四角全切会显得像八边形按钮；黄色角标每屏最多一两处。"},"prompt":"实现切角工业面板：clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% − var(--cut)), calc(100% − var(--cut)) 100%, 0 100%, 0 var(--cut))，标准 --cut 14px；变体：深色反色模块（右上黄色三角角标、底部 12px 黄黑 −45° 危险斜纹）、文件夹标签切口（顶边 46% 处 16px 台阶）。四角放 14×14 十字注册标记（两条 2px 线），标题下方加 1px/8px 刻度尺。入场：--cut 从 134px 以 cubic-bezier(.2,.9,.1,1) 450ms 收拢到 14px 并上移 24px→0，面板错峰 120ms，附件在其后错峰出现。","demo":"demos/patterns/chamfer-panel/index.html","kit":true,"previewAt":1.4,"sources":[{"caseId":"industrial-protocol","observation":"终端、配装站与角色信息面板复用 Logo 衍生图形与三角形元素，界面整体呈工业机能风格。","evidence":"inferred","locator":"17173 评析"}],"preview":"previews/patterns/chamfer-panel.jpg","previewPortrait":null},{"id":"text-scramble","order":51,"title":"字符解码","types":["type-motion"],"carriers":["console","video","showcase"],"summary":"标题与编码先显示为随机字符，再按从左到右（带随机抖动）的阈值逐个“解出”，末尾跟一个块状光标；随机由帧号与位置决定，逐帧渲染也一致。","mechanism":"每个字符的解出阈值 = (i / n) × 0.7 + rng × 0.3；进度 p 超过阈值即显示真实字符，否则显示字符集中的随机字符（rng(seed, i, floor(t × 24))）；未解出的字符用强调色；中文可用同主题汉字集替代拉丁字符集。","trigger":"标题出现 / 数据刷新 / 换页","effect":"“系统正在读取”的科技感，比打字更快、更有密度。","timing":[{"name":"刷新率","value":"24fps"},{"name":"时长","value":"0.6–1.2s（随长度）"},{"name":"阈值分布","value":"位置 70% + 随机 30%"}],"useCases":["终端标题","编码/编号显示","换页标题","科幻影视字幕"],"avoid":["正文与长句","屏幕阅读器场景（需 aria-label 提供原文）"],"accessibility":{"reducedMotion":"直接显示原文。","keyboard":"原文写入 aria-label，读屏不会读到乱码。"},"composition":{"role":"accent","pairsWellWith":["chamfer-panel","scanline-wipe","boot-typing"],"conflicts":[],"notes":"同屏解码不要超过两处；解码完成后保持静止。"},"prompt":"实现字符解码：输入 text、进度 p、帧号 tick=floor(t×24)。为每个字符预先生成解出阈值 (i/n)×0.7 + rng(seed)×0.3；p ≥ 阈值显示原字符，否则显示字符集（A–Z、0–9、#/%+=<>；中文用同主题汉字集）中由 rng(seed×131 + i×17 + tick×7919) 选出的随机字符，并以强调色显示；未完成时末尾显示黄色块状光标。原文写入 aria-label。所有随机都由种子与帧号决定，可逐帧复现。","demo":"demos/patterns/text-scramble/index.html","kit":true,"previewAt":1.2,"sources":[{"caseId":"industrial-protocol","observation":"评析提到界面中的文字动画演出效果与高质量动态视觉；具体解码形式为本库转译。","evidence":"inferred","locator":"17173 评析 · 待核验"}],"preview":"previews/patterns/text-scramble.jpg","previewPortrait":null},{"id":"conveyor-flow","order":52,"title":"产线流动","types":["hud","rhythm"],"carriers":["console","showcase","video"],"summary":"节点之间的正交传送带上，物料方块匀速流动、带纹同速推进、节点指示灯闪烁、产量计数——持续运转的系统感来自“永不停的匀速”。","mechanism":"路径为带圆角的正交折线（灰色粗底 + 黑色虚线带纹）；物料位置 = getPointAtLength(L × ((t × v / L + i / n) mod 1))，带纹 stroke-dashoffset = −t × v；全部只依赖时间。状态变化（如部署加速）只改变 v。","trigger":"常驻（后台运行）","effect":"画面始终“在工作”，与离散的交互事件形成节奏对比。","timing":[{"name":"速度","value":"90px/s（加速 150px/s）"},{"name":"密度","value":"每条带 4–5 个物料"},{"name":"圆角","value":"14–16px"}],"useCases":["产线/物流监控","数据管道可视化","游戏建造界面","流程说明影像"],"avoid":["真实需要精确吞吐数值的监控（示意动画可能误导）"],"accessibility":{"reducedMotion":"物料静止在固定位置，计数直接显示。","keyboard":"参数为原生滑杆。"},"composition":{"role":"support","pairsWellWith":["chamfer-panel","hold-confirm"],"conflicts":[],"notes":"匀速运动不要加缓动；与离散事件的“snap”形成对比。"},"prompt":"实现产线流动：在 SVG 中为每条连接生成正交折线路径（M x1 y1 H mx−r Q … V … Q … H x2），先画 14px 灰色底，再画 2px 黑色 6/10 虚线带纹；每帧带纹 strokeDashoffset = −t×v；每条带放 n 个旋转 45° 的小方块，位置 = path.getPointAtLength(L×(((t×v/L + i/n) % 1 + 1) % 1))。节点为切角白盒 + 编码 + 计数 + 闪烁绿灯。提供速度与物料数滑杆；SVG 文字按缩放换算保证 ≥12px。","demo":"demos/patterns/conveyor-flow/index.html","kit":true,"previewAt":2,"sources":[{"caseId":"industrial-protocol","observation":"集成工业系统在菜单中规划与模拟产线；传送带流动的可视化为本库转译。","evidence":"inferred","locator":"GameWith 攻略 · 待核验"}],"preview":"previews/patterns/conveyor-flow.jpg","previewPortrait":null},{"id":"hold-confirm","order":53,"title":"长按确认","types":["feedback"],"carriers":["console","showcase"],"summary":"不可逆操作需要按住：进度只在按住时增长，松开以 300ms 回落；满格瞬间锁定为完成态并盖章——比二次弹窗更有“物理”感。","mechanism":"记录每次按下/松开的时刻；进度 = (min(松开, t) − 按下) / 时长，松开后乘以回落系数；按住时长 ≥ 阈值（带 1e-6 容差）即在“按下 + 阈值”时刻完成。按钮同时支持指针与空格/回车（忽略按键重复），标签实时显示百分比。","trigger":"部署 / 删除 / 提交等不可逆操作","effect":"防误触，同时让确认本身成为一段有张力的交互。","timing":[{"name":"时长","value":"1.2s 线性"},{"name":"回落","value":"300ms outCubic"},{"name":"完成印章","value":"350ms outBack，1.5→1，−8°"}],"useCases":["部署/发射/提交","删除与重置","游戏中的蓄力确认"],"avoid":["高频操作（会拖慢效率）","运动障碍用户的唯一入口（需提供替代确认）"],"accessibility":{"reducedMotion":"进度直接显示，无回弹。","keyboard":"聚焦后按住空格/回车；aria-describedby 说明需要按住。"},"composition":{"role":"accent","pairsWellWith":["chamfer-panel","conveyor-flow"],"conflicts":[],"notes":"完成后要有明确的状态变化（文字 + 印章 + 系统反馈），否则用户不确定是否成功。"},"prompt":"实现长按确认按钮：切角深色按钮，右侧黄黑危险斜纹；按下（pointerdown 或聚焦后空格/回车，忽略 repeat）记录开始时刻，松开记录结束；进度 = clamp((min(end, t) − start)/1.2s)，松开过早时以 300ms outCubic 回落到 0；当 (end ?? t) − start ≥ 1.2s − 1e-6 时在 start+1.2s 锁定完成：标签变为 DEPLOYED，盖下倾斜 −8° 的绿色描边印章（350ms outBack 1.5→1）。上方配一个同步的圆环进度。按钮 aria-describedby 指向“需按住 1.2 秒”的说明。","demo":"demos/patterns/hold-confirm/index.html","kit":true,"previewAt":4.2,"sources":[{"caseId":"industrial-protocol","observation":"部署/建造等确认操作；长按形式为本库转译。","evidence":"inferred","locator":"交互转译 · 待核验"}],"preview":"previews/patterns/hold-confirm.jpg","previewPortrait":null},{"id":"scanline-wipe","order":54,"title":"扫描线换页","types":["transition"],"carriers":["console","showcase","video"],"summary":"一条发光的黄色扫描线从左扫到右：线左是新页、线右仍是旧页，像被设备重新扫描刷新；新页卡片在线经过后错峰上浮。","mechanism":"新页 clip-path: inset(0 (1−x)% 0 0)，旧页 clip-path: inset(0 0 0 x%)，x 用 inOutQuart 500ms 从 0 到 1；扫描线是 3px 黄线 + 外发光，后面跟一段淡黄拖影；新页内容在 x 过半后以 snap 错峰进入。","trigger":"模块/页签切换","effect":"比淡入更有“系统刷新”感，并且方向明确。","timing":[{"name":"扫描","value":"500ms inOutQuart"},{"name":"卡片","value":"扫描过半后 320ms snap，错峰 60ms"}],"useCases":["操作台页签切换","数据刷新","影像中的界面换页"],"avoid":["高频切换（每次 0.5s 会拖慢）"],"accessibility":{"reducedMotion":"直接切换页面。","keyboard":"页签为原生按钮/role=tab。"},"composition":{"role":"support","pairsWellWith":["chamfer-panel","text-scramble"],"conflicts":[],"notes":"只在内容区扫描，顶栏与侧栏不动，保持“同一台设备”。"},"prompt":"实现扫描线换页：内容容器内叠放各页；切换时 x 以 500ms inOutQuart 从 0→1，新页 clip-path: inset(0 calc((1−x)×100%) 0 0)、旧页 clip-path: inset(0 0 0 calc(x×100%))，其余页隐藏；一条 3px 黄色竖线位于 left: x×100%，带 0 0 26px 7px 的黄色外发光，左侧跟随 18% 宽的淡黄拖影；新页卡片在扫描过半后以 cubic-bezier(.2,.9,.1,1) 320ms 错峰 60ms 上浮 18px→0。","demo":"demos/patterns/scanline-wipe/index.html","kit":true,"previewAt":0.85,"sources":[{"caseId":"industrial-protocol","observation":"模块切换的界面刷新；扫描线形式为本库转译。","evidence":"inferred","locator":"交互转译 · 待核验"}],"preview":"previews/patterns/scanline-wipe.jpg","previewPortrait":null},{"id":"lower-third","order":60,"title":"三段式下三分之一","types":["type-motion","hud"],"carriers":["video","console"],"summary":"人物条按“色条 → 底板 → 文字”三段入场，离场倒序且更快；时长按拍写，整条节目的人物条都踩在同一个节奏上。","mechanism":"色条 scaleY 0→1（200ms，从底部长出）；底板用 clip-path 多边形从色条处向右擦出，右端保留斜切（350ms snap）；标签/姓名/职位三行 80ms 错峰上浮 14px；离场：文字 140ms 先淡出 → 底板 220ms 收回 → 色条 180ms 缩回。","trigger":"人物出镜 / 发言","effect":"信息分层出现，视线依次被“颜色 → 名字 → 身份”引导。","timing":[{"name":"色条","value":"200ms outCubic"},{"name":"底板","value":"350ms snap，延迟 150ms"},{"name":"文字","value":"300ms outCubic，错峰 80ms"},{"name":"离场","value":"约入场的 60%，倒序"}],"useCases":["直播/节目人物条","纪录片字幕条","发布会讲者介绍"],"avoid":["同时出现两条以上"],"accessibility":{"reducedMotion":"直接显示完整人物条。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["stinger-bars","corner-hud"],"conflicts":[],"notes":"与得分、数据等中央事件错开至少 1 拍。"},"prompt":"实现三段式下三分之一：左侧 14px 强调色竖条 scaleY 0→1（200ms，transform-origin 底部）；右侧深色底板 clip-path: polygon(0 0, P% 0, calc(P% − 28px) 100%, 0 100%)，P 在 350ms 内以 cubic-bezier(.2,.9,.1,1) 从 0 到 100（延迟 150ms）；标签（12px 等宽强调色）、姓名（超粗斜体）、职位（宽字距）三行 80ms 错峰上浮 14px；右上角一个品红“LIVE”胶囊回弹出现。离场倒序：文字 140ms → 底板 220ms → 色条 180ms。入场与离场时刻用 BPM 拍号计算。","demo":"demos/patterns/lower-third/index.html","kit":true,"previewAt":1.6,"sources":[{"caseId":"broadcast-pack","observation":"原创转播包中的人物条入场语法。","evidence":"original","locator":"第 8–15 拍"}],"preview":"previews/patterns/lower-third.jpg","previewPortrait":null},{"id":"stinger-bars","order":61,"title":"色带转场 Stinger","types":["transition"],"carriers":["video","console","showcase"],"summary":"多条斜色带错峰横扫，第一条盖住画面的那一刻完成场景硬切，品牌标志在色带中段闪现——观众只看到“品牌”，看不到切换。","mechanism":"N 条宽 34%、skewX(−18°) 的色带，left 从 −60% 到 160%（2 拍 inOutCubic），错峰 70ms；场景在转场时长 50% 时切换（被色带完全遮住）；标志在 35%–62% 区间回弹出现再缩回。","trigger":"直播 ↔ 回放 / 段落切换","effect":"切换被品牌化，节奏清楚且没有黑场。","timing":[{"name":"长度","value":"2 拍（120 BPM = 1s）"},{"name":"错峰","value":"70ms/条"},{"name":"切换点","value":"转场 50%"},{"name":"标志","value":"35%–62% 区间，outBack 弹出"}],"useCases":["回放进出","节目段落切换","短视频转场"],"avoid":["安静内容（会显得吵）"],"accessibility":{"reducedMotion":"改为直接切换或 200ms 淡入淡出。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"support","pairsWellWith":["lower-third","cutin-slash"],"conflicts":[],"notes":"色带颜色取自品牌色角色，最后一条用深底色，保证收尾干净。"},"prompt":"实现色带 stinger：全屏 overflow:hidden 容器内放 5 条 width 34%、top/bottom −20%、transform: skewX(−18deg) 的色带（品牌色依次排列，最后一条深色），每条 left 在 2 拍内以 inOutCubic 从 −60% 走到 160%，错峰 70ms；在转场 50% 时刻切换底下的场景；标志在 35% 处 outBack 弹出、62% 处缩回。时长按 BPM 计算。","demo":"demos/patterns/stinger-bars/index.html","kit":true,"previewAt":1.25,"sources":[{"caseId":"broadcast-pack","observation":"原创转播包的开场、回放进出与结尾转场。","evidence":"original","locator":"第 0、28、36、46 拍"}],"preview":"previews/patterns/stinger-bars.jpg","previewPortrait":null},{"id":"beat-clock","order":62,"title":"BPM 节拍时钟与前瞻调度","types":["rhythm","sound"],"carriers":["video","console","showcase"],"summary":"用 beat = t ÷ (60 / BPM) 把时间换成拍；视觉用“每拍脉冲”，声音用“前瞻调度”交给 AudioContext 定时播放——画面与声音落在同一拍上。","mechanism":"拍位置 beat = (t − offset) / spb；脉冲 = e^(−k·frac(beat))；小节 = floor(beat / 4)。声音：预先生成事件表（十六分音符步进），每帧把 [t, t + 120ms) 内的事件以 delay = 事件时刻 − t 交给 WebAudio；拖动或倒放时重置游标；循环时提前排入下一圈开头。BPM 改变时按相对位置重算时长。","trigger":"播放 / 拖动 / 改 BPM","effect":"所有动效有统一的时间网格，音画同步不受帧率抖动影响。","timing":[{"name":"拍长","value":"60 / BPM 秒（110 BPM ≈ 545ms）"},{"name":"脉冲衰减","value":"k = 6–10"},{"name":"前瞻","value":"100–150ms"}],"useCases":["卡点视频","音乐可视化","节奏游戏界面","直播包装踩拍"],"avoid":["无节拍的环境音场景"],"accessibility":{"reducedMotion":"保留节拍网格高亮，关闭缩放脉冲。","keyboard":"BPM 为原生滑杆；空格播放/暂停。"},"composition":{"role":"foundation","pairsWellWith":["word-slam","seekable-timeline","stinger-bars"],"conflicts":[],"notes":"先定 BPM 与第一拍偏移，再写所有动画的拍号；不要用秒写死。"},"prompt":"实现 BPM 节拍时钟：spb = 60/bpm，beat = (t − offset)/spb，提供 at(beat)、beatOf(t)、pulse(t, k) = e^(−k·frac(beat))、quantize(t, div)。界面：一个随拍脉冲的圆（小节首拍变强调色）、16 步网格高亮当前步、BAR/BEAT/STEP 与 ms/拍 读数、BPM 滑杆（修改后按相对位置重算时长）。声音：生成十六分音符事件表（底鼓/军鼓/镲片字符串 “x...”），每帧把 [t, t+120ms) 的事件以 delay = 事件时刻 − t 调度给 WebAudio，拖动后重置游标，循环时提前排入下一圈。","demo":"demos/patterns/beat-clock/index.html","kit":true,"previewAt":2.2,"sources":[{"caseId":"beat-lyric","observation":"节拍字幕的全部视觉事件与合成鼓点共用一个拍号时钟。","evidence":"original","locator":"全片"},{"caseId":"broadcast-pack","observation":"转播包按 120 BPM 拍号编排所有图形。","evidence":"original","locator":"全片"}],"preview":"previews/patterns/beat-clock.jpg","previewPortrait":null},{"id":"word-slam","order":63,"title":"逐词重拍","types":["type-motion","rhythm"],"carriers":["video","showcase"],"summary":"每个词落在一个拍上：瞬间从 1.5 倍“敲”下去（120ms），持续若干拍后硬切到下一个词；反拍给一个很小的上弹——静止的字也在跟着律动。","mechanism":"当前词 = 拍号 ≤ 当前拍的最后一个；k = outExpo((t − 词起点)/120ms)，scale = lerp(1.5, 1, k)、rotate = (1 − k)·(−3°)；进入词后 0.5 拍起，位移 −2%·e^(−10·Δ) 的上弹；每小节首拍切换底色。没有任何淡入淡出。","trigger":"拍点","effect":"强烈的“卡点”感，观众能用眼睛数拍。","timing":[{"name":"落定","value":"120ms outExpo，1.5→1"},{"name":"反拍","value":"+0.5 拍上弹 2%"},{"name":"换色","value":"每小节首拍"}],"useCases":["歌词视频","口号/标语影片","倒计时","发布会开场"],"avoid":["需要阅读完整句子的场景（每次只显示一个词）"],"accessibility":{"reducedMotion":"只切换文字，不做缩放与上弹。","keyboard":"空格播放/暂停，←/→ 跳 1 秒，Shift+←/→ 跳到上/下一个标记。"},"composition":{"role":"foundation","pairsWellWith":["beat-clock","ransom-type"],"conflicts":[],"notes":"词的长度差异大时可按字数缩放字号，保证每个词占满主体。"},"prompt":"实现逐词重拍：词表 [{b: 拍号, w: 词}]，当前词 = b ≤ 当前拍的最后一个；出现瞬间以 120ms outExpo 从 scale 1.5、rotate −3° 落定到 1、0°；进入该词 0.5 拍后加一个 −2% 的上弹并以 e^(−10Δ) 回落；每小节首拍在两组 [底色, 字色] 间切换；完全不使用淡入淡出（硬切）。底部 4 格拍点指示当前拍。","demo":"demos/patterns/word-slam/index.html","kit":true,"previewAt":0.7,"sources":[{"caseId":"beat-lyric","observation":"WE / MOVE / ON THE / ONE 与 STAY ON THE ONE 段落的拍入语法。","evidence":"original","locator":"第 4–7、40–43 拍"}],"preview":"previews/patterns/word-slam.jpg","previewPortrait":null},{"id":"radar-sweep","order":70,"title":"雷达扫描与余辉","types":["hud","rhythm"],"carriers":["console","video"],"summary":"扫描线匀速旋转，身后拖一段锥形余辉；目标在被扫到的瞬间最亮，随后按指数衰减，并向外扩一圈——像荧光屏的余晖。","mechanism":"扫描角 = t / 周期 × 2π；余辉为 createConicGradient 的扇区（角宽 W，从透明到 α≈0.2）；目标亮度 I = e^(−k·Δt)，Δt = ((扫描角 − 目标方位) mod 2π) / 2π × 周期；扩散环半径随 1 − I 增大。全部只依赖时间。","trigger":"常驻","effect":"“系统在持续侦测”，同时目标的出现有节奏感。","timing":[{"name":"周期","value":"4s/圈（可 1.5–8s）"},{"name":"余辉","value":"角宽 50–70°，α 0.18–0.2"},{"name":"衰减","value":"k ≈ 1.3"}],"useCases":["FUI 与监控大屏","游戏小地图","位置/设备发现动画"],"avoid":["需要精确实时位置的真实监控（余辉会让位置滞后）"],"accessibility":{"reducedMotion":"扫描停止，目标以常亮显示。","keyboard":"参数为原生滑杆。"},"composition":{"role":"foundation","pairsWellWith":["target-lock","alert-state"],"conflicts":[],"notes":"扫描周期可以作为整台界面的基础节拍。"},"prompt":"在 Canvas 上实现雷达扫描：同心圆、十字线、每 30° 方位刻度（字号按画布缩放换算 ≥12px）；扫描角 = t/周期×2π（从正北顺时针）；用 createConicGradient 在扫描线身后画角宽约 52° 的扇形余辉（从透明到 α0.2）；扫描线 3px 实线；每个目标亮度 I = e^(−1.3×Δt)，Δt 为扫描线离开它的秒数，被扫到时外扩一圈半径随 (1−I) 增大的描边环；未知目标用菱形。提供周期、衰减、余辉角滑杆。","demo":"demos/patterns/radar-sweep/index.html","kit":true,"previewAt":0.6,"sources":[{"caseId":"mission-fui","observation":"指挥台中央雷达。","evidence":"original","locator":"全片"}],"preview":"previews/patterns/radar-sweep.jpg","previewPortrait":null},{"id":"target-lock","order":71,"title":"阶梯式目标锁定","types":["feedback"],"carriers":["console","video"],"summary":"锁定框不是平滑缩放，而是分档“咔、咔、咔”收紧并旋正，最后等一段确认时间才显示 LOCK——锁定有了机械感和重量。","mechanism":"尺寸序列（如 240→180→120→80→48），档位 i = floor(Δt / 档间隔)，档内用 snap 缓动 80ms；旋转 45°×(1 − 进度)；确认时长后标签从 ACQ ■■□□ 进度切换为 LOCK。","trigger":"选择目标","effect":"“系统在计算”的可信感，比一下子框住更有张力。","timing":[{"name":"档位","value":"240 → 180 → 120 → 80 → 48 px"},{"name":"每档","value":"snap 80ms，间隔 150ms"},{"name":"确认","value":"1.4–1.6s"}],"useCases":["FUI 锁定","游戏瞄准/选中","扫码/识别成功反馈"],"avoid":["需要即时响应的高频选择"],"accessibility":{"reducedMotion":"直接显示最终框与 LOCK。","keyboard":"目标为可聚焦按钮。"},"composition":{"role":"accent","pairsWellWith":["radar-sweep","alert-state","text-scramble"],"conflicts":[],"notes":"锁定后的数据用打字/解码出现，延续“计算”的语义。"},"prompt":"实现阶梯式锁定框：四个 18px L 形角（3px 描边）组成的方框，以目标为中心；尺寸按 [240,180,120,80,48] 分档收紧，档位 i = clamp(floor((t−t0)/0.15), 0, 3)，档内 80ms cubic-bezier(.2,.9,.1,1)；同时 rotate 从 45° 线性回到 0°；右上标签在确认前显示 ACQ ■■□□（每 0.35s 多一格），1.4s 后显示 LOCK + 目标编号。点击目标重新锁定。","demo":"demos/patterns/target-lock/index.html","kit":true,"previewAt":0.85,"sources":[{"caseId":"mission-fui","observation":"指挥台锁定 X-07。","evidence":"original","locator":"6.0s"}],"preview":"previews/patterns/target-lock.jpg","previewPortrait":null},{"id":"alert-state","order":72,"title":"全局告警态切换","types":["composition","rhythm"],"carriers":["console","video","showcase"],"summary":"一个状态变量同时决定全部颜色、闪烁频率、边缘辉光与数据波动；组件只读 CSS 变量，切换一次整台设备一起变。","mechanism":"状态表：{主色, 暗色, 底色, 面板色, 闪烁 Hz, 辉光强度, 抖动幅度}；切换时 400ms 插值写入 CSS 变量；闪烁用 floor(t × Hz × 2) 的方波（同一时钟）；ALERT 的边缘辉光以 2Hz 正弦脉冲；数据目标值与抖动幅度随状态改变。","trigger":"系统状态变化","effect":"状态一目了然，且“紧张度”可以分级。","timing":[{"name":"颜色","value":"400ms inOutCubic"},{"name":"闪烁","value":"NOMINAL 0 · CAUTION 1Hz · ALERT 2Hz"},{"name":"辉光","value":"CAUTION 静态 8px · ALERT 26px 2Hz 脉冲"}],"useCases":["监控/告警系统","游戏警戒状态","倒计时紧张阶段","直播事件强调"],"avoid":["频繁来回切换（会让用户疲劳）","超过 3Hz 的闪烁"],"accessibility":{"reducedMotion":"颜色切换保留，闪烁与脉冲关闭。","keyboard":"状态按钮为原生 button，1/2/3 快捷键；状态标签 role=status。"},"composition":{"role":"foundation","pairsWellWith":["radar-sweep","target-lock","corner-hud"],"conflicts":[],"notes":"颜色之外，一定要同时改变“节奏”（闪烁/脉冲），才能让紧张度被身体感知。"},"prompt":"实现全局告警态：定义状态表 nominal/caution/alert，每个包含 main/dim/bg/panel 颜色、闪烁 Hz（0/1/2）、边缘辉光强度（0/8/26）、数据抖动幅度；切换时用 400ms inOutCubic 把颜色插值写入 :root 的 CSS 变量，所有组件只读变量；状态标签按 floor(t×Hz×2)%2 方波闪烁；ALERT 时全屏 inset box-shadow 以 2Hz 正弦脉冲；数据卡片的目标值与抖动随状态改变。提供 1/2/3 快捷键与按钮，减少动态时关闭闪烁与脉冲。","demo":"demos/patterns/alert-state/index.html","kit":true,"previewAt":5.5,"sources":[{"caseId":"mission-fui","observation":"指挥台 NOMINAL → CAUTION → ALERT → NOMINAL。","evidence":"original","locator":"9.5–16.6s"}],"preview":"previews/patterns/alert-state.jpg","previewPortrait":null},{"id":"charge-release","order":73,"title":"蓄力—预示—爆发","types":["rhythm","transition"],"carriers":["showcase","video","console"],"summary":"期待感 = 时长 × 不确定性：粒子螺旋内收蓄力，预示色先给一部分答案，最高等级先给次一级颜色再升格（假动作），最后用最强的闪白与冲击波释放。","mechanism":"蓄力进度 c（inCubic）驱动粒子角速度 ×(1+3c)、半径 ×(1−0.92c)、光球缩放；预示时刻设置颜色变量并给弱闪白；升格时刻换色 + 光球抖动 + 中闪白；爆发后粒子 outExpo 径向飞散、冲击波椭圆扩张、强闪白 e^(−5t)。","trigger":"开始揭示","effect":"让结果出现前的一两秒充满张力，结果出现时有释放感。","timing":[{"name":"蓄力","value":"1.3–2.3s inCubic"},{"name":"预示→爆发","value":"0.8–0.9s（含 0.45s 升格）"},{"name":"闪白","value":"0.35 / 0.7 / 1.0 三档"}],"useCases":["抽卡/开箱","开奖/揭晓","技能释放","发布会揭幕"],"avoid":["频繁的小操作（会显得拖沓）"],"accessibility":{"reducedMotion":"不闪白、不抖动，直接给出结果色。","keyboard":"稀有度按钮为原生 button。"},"composition":{"role":"foundation","pairsWellWith":["card-flip-sheen","impact-pop"],"conflicts":[],"notes":"升格假动作只给最高等级使用，过度使用会让用户不再相信预示色。"},"prompt":"实现蓄力—预示—爆发：Canvas 中 140 个固定种子粒子，按下后进度 c=inCubic((t−press)/(burst−press))，粒子角度 a0+(t−press)×w×(1+3c)、半径 r0×(1−0.92c) 螺旋内收；中心光球（发光环 + 核心）缩放 0.25+1.1c；tell 时刻把颜色变量设为最高稀有度色（若为最高级先给次一级）并 0.35 闪白，upgrade 时刻升格、光球 ±4px 抖动并再放大 0.25、0.7 闪白；burst 时刻 1.0 闪白（e^(−5t) 衰减）、椭圆冲击波、粒子 outExpo 径向飞散 1.2s。提供 ★3/★4/★5 切换。","demo":"demos/patterns/charge-release/index.html","kit":true,"previewAt":2.3,"sources":[{"caseId":"gacha-reveal","observation":"抽卡舞台的蓄力、预示、升格与爆发。","evidence":"original","locator":"0.6–2.9s"}],"preview":"previews/patterns/charge-release.jpg","previewPortrait":null},{"id":"card-flip-sheen","order":74,"title":"翻牌与流光","types":["feedback","transition"],"carriers":["showcase","console","video"],"summary":"卡片以 outBack 翻转 180°（略超再回正，像真的翻过去），翻开后一道斜向流光扫过牌面；稀有卡多停一拍再翻，翻开后发光并轻微放大。","mechanism":"父元素 transform-style: preserve-3d，正反两面 backface-visibility: hidden，正面预先 rotateY(180°)；翻转 rotateY = clamp(outBack(p), 0, 1.08)×180°；流光是 105° 线性渐变条，translateX −100%→100%；稀有卡额外延迟与外发光脉冲。","trigger":"揭示结果 / 点击卡片","effect":"每张卡都是一次小揭示，稀有卡被“停顿”放大。","timing":[{"name":"翻转","value":"450ms outBack"},{"name":"流光","value":"600ms，延迟 300ms"},{"name":"错峰","value":"120–250ms"},{"name":"稀有停顿","value":"0.6–0.7s"}],"useCases":["卡牌/奖励揭示","翻卡记忆游戏","产品特性卡片","答案揭晓"],"avoid":["大量卡片同时翻转（失去节奏）"],"accessibility":{"reducedMotion":"直接显示正面。","keyboard":"卡片为原生 button，带名称与星级的可访问名称。"},"composition":{"role":"accent","pairsWellWith":["charge-release","decrypt-reveal"],"conflicts":[],"notes":"翻牌顺序按阅读顺序，稀有卡永远最后。"},"prompt":"实现翻牌与流光：卡片 button 设 transform-style: preserve-3d，内含背面（斜纹 + 稀有度描边发光）与正面（渐变 + 图形 + 名称，预先 rotateY(180deg)），两面 backface-visibility: hidden。第 i 张在 start + i×0.25s（稀有卡再加 0.6s）开始，rotateY = clamp(outBack(p), 0, 1.08)×180°（450ms）；翻开后 300ms 一条 105° 白色流光 600ms 从左扫到右；稀有卡外发光脉冲并 scale 1.08 回落。点击单张卡可重翻。","demo":"demos/patterns/card-flip-sheen/index.html","kit":true,"previewAt":1.9,"sources":[{"caseId":"gacha-reveal","observation":"十连结果的逐张翻牌与金卡停顿。","evidence":"original","locator":"4.1–6.6s"}],"preview":"previews/patterns/card-flip-sheen.jpg","previewPortrait":null},{"id":"ink-bleed","order":75,"title":"墨晕显影","types":["transition","texture"],"carriers":["showcase","video"],"summary":"扩散遮罩经过湍流位移，边缘像墨在宣纸上洇开；位移与模糊随显影完成逐渐归零，最后得到清晰的墨色。","mechanism":"SVG mask 内放一个径向渐变矩形，渐变的边缘 offset 随时间外推；矩形套用 feTurbulence + feDisplacementMap（scale 由大到小）+ feGaussianBlur（由大到小）；被遮罩的内容是墨色渐变山形。超宽画面要把滤镜区域限定在可见范围，并在完成后移除滤镜。","trigger":"画面出现 / 揭示","effect":"比淡入更有“材料感”，东方审美的显影方式。","timing":[{"name":"扩散","value":"1.6–2.2s outCubic"},{"name":"位移","value":"90 → 18（或 0）"},{"name":"模糊","value":"4–6 → 0"}],"useCases":["水墨/东方风格展示","品牌片头","文旅与博物馆"],"avoid":["低性能设备上的超大画面（滤镜开销大）"],"accessibility":{"reducedMotion":"不做扰动与模糊，直接显示。","keyboard":"参数为原生滑杆。"},"composition":{"role":"support","pairsWellWith":["seal-stamp","vertical-title-blur"],"conflicts":[],"notes":"多层山水按远→近依次晕开，间隔 0.6–0.8s。"},"prompt":"实现墨晕显影：SVG 中定义 mask（userSpaceOnUse），里面是一个填充径向渐变的全幅矩形，渐变两个色标的 offset 随时间从 0 外推到 1.25（outCubic，约 2s），矩形应用 filter：feTurbulence(fractalNoise, baseFrequency .018, 3 octaves) → feDisplacementMap(scale 由 90 降到 18) → feGaussianBlur(stdDeviation 由 4 降到 0)。被遮罩内容是墨色竖向渐变的山形 + 山脊描边。提供扩散时长与扰动强度滑杆；减少动态时直接显示。","demo":"demos/patterns/ink-bleed/index.html","kit":true,"previewAt":1.4,"sources":[{"caseId":"ink-scroll","observation":"长卷远、中、近三层依次晕开。","evidence":"original","locator":"2.2–5.4s"}],"preview":"previews/patterns/ink-bleed.jpg","previewPortrait":null},{"id":"seal-stamp","order":76,"title":"印章落下","types":["feedback"],"carriers":["showcase","video"],"summary":"抬起（影子变大变淡）→ 按下（1.35→1 回弹、轻微旋转）→ 印泥晕开（红色扩散环）→ 纸面微震与一声低频“咚”：一个确认动作的完整物理过程。","mechanism":"按下前 350ms 印章半透明放大 1.5、影子模糊扩大；按下 260ms outBack 从 1.35 缩到 1、−6°→−2°；按下后 100ms 起红色描边环 0.8s 扩到 16 倍并淡出；容器微震 6px·e^(−14t)；低频正弦下滑音 + 短噪声。","trigger":"确认 / 完成 / 签署","effect":"把“完成”变成一个有重量、有仪式感的动作。","timing":[{"name":"抬起","value":"350ms outCubic"},{"name":"按下","value":"260ms outBack，1.35→1"},{"name":"扩散环","value":"0.8s"},{"name":"微震","value":"6px·e^(−14t)"}],"useCases":["完成/签署确认","文旅打卡盖章","长卷与证书结尾","任务完成"],"avoid":["高频操作"],"accessibility":{"reducedMotion":"无震动，印章直接出现。","keyboard":"纸面可聚焦，回车在中心盖章。"},"composition":{"role":"accent","pairsWellWith":["ink-bleed","hold-confirm"],"conflicts":[],"notes":"印章是画面中唯一的强彩色，放在阅读终点。"},"prompt":"实现印章落下：点击位置为落点；落下前 350ms 印章以 1.5 倍、半透明出现在上方，下方投影放大模糊；按下时 260ms outBack 从 scale 1.35 落到 1、rotate −6°→−2°，投影迅速变小消失；100ms 后一圈 3px 印泥色描边环 0.8s 扩大到 16 倍并淡出；纸面 translate 微震 6px·e^(−14t)；声音 90Hz 下滑正弦 + 80ms 低通噪声。纸面可聚焦，回车在中心盖章。","demo":"demos/patterns/seal-stamp/index.html","kit":true,"previewAt":1.3,"sources":[{"caseId":"ink-scroll","observation":"长卷卷尾钤印。","evidence":"original","locator":"12.0s"}],"preview":"previews/patterns/seal-stamp.jpg","previewPortrait":null}]};
